local function loadRaceMetadata()
	local modules = ReplicatedStorage:WaitForChild("Modules", 45)
	local metadata = modules and modules:WaitForChild("Metadata", 20)
	local raceFolder = metadata and metadata:WaitForChild("RaceData", 20)
	local raceBuffModule = raceFolder and raceFolder:FindFirstChild("RaceBuffs")
	local subTypeModule = raceFolder and raceFolder:FindFirstChild("SubTypeData")
	if not raceBuffModule or not subTypeModule then
		setStatus("RaceData modules not found on this place.", colors.Danger)
		return false
	end
	local okBuffs, raceBuffs = pcall(require, raceBuffModule)
	local okSubTypes, subTypeData = pcall(require, subTypeModule)
	if not okBuffs or type(raceBuffs) ~= "table" or not okSubTypes or type(subTypeData) ~= "table" then
		setStatus("Could not require race metadata.", colors.Danger)
		return false
	end
	table.clear(raceOrder)
	table.clear(traitsByRace)
	for race in pairs(raceBuffs) do
		local subtypeList = subTypeData[race .. "SubTypes"]
		if type(subtypeList) == "table" then
			local traits = {}
			for _, entry in ipairs(subtypeList) do
				if type(entry) == "table" and type(entry[1]) == "string" then
					table.insert(traits, entry[1])
				end
			end
			if #traits > 0 then
				traitsByRace[race] = traits
				table.insert(raceOrder, race)
			end
		end
	end
	table.sort(raceOrder)
	if #raceOrder == 0 then
		setStatus("No races parsed from metadata.", colors.Danger)
		return false
	end
	selectedRace = raceOrder[1]
	selectedTrait = traitsByRace[selectedRace][1]
	raceButton.Text = "Race: " .. selectedRace .. "  v"
	traitButton.Text = "Trait: " .. tostring(selectedTrait) .. "  v"
	setStatus("Pick race + trait, then Apply (uses menu/server remotes when linked).", colors.Success)
	refreshInfo()
	return true
end

local function readAuthoritativeRaceTrait()
	if not remotesReady or not statRetrieveRemote then
		return nil, nil
	end
	local okRace, race = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "Race")
	local okTrait, trait = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "SubType")
	return okRace and race or nil, okTrait and trait or nil
end

local function invokeRemoteInstance(remote, ...)
	if not remote or not remote.Parent or not remote:IsA("RemoteFunction") then
		return false, "invalid remote"
	end
	return pcall(remote.InvokeServer, remote, ...)
end

local function fireRemoteInstance(remote, ...)
	if not remote or not remote.Parent or not remote:IsA("RemoteEvent") then
		return false, "invalid remote"
	end
	return pcall(remote.FireServer, remote, ...)
end

local function invokeRemoteFunction(name, ...)
	local remote = findGameRemote(name)
	if not remote or not remote:IsA("RemoteFunction") then
		return false, "missing " .. tostring(name)
	end
	rememberRemote(remote)
	return invokeRemoteInstance(remote, ...)
end

local function fireRemoteEvent(name, ...)
	local remote = findGameRemote(name)
	if not remote or not remote:IsA("RemoteEvent") then
		return false, "missing " .. tostring(name)
	end
	rememberRemote(remote)
	return fireRemoteInstance(remote, ...)
end

local PROBE_TIMEOUT = 2.5
local APPLY_TIMEOUT = 8
local MAX_AUTO_SPINS = 40

local function invokeRemoteFunctionWithTimeout(name, timeoutSeconds, ...)
	local packed = table.pack(...)
	local timeout = timeoutSeconds or PROBE_TIMEOUT
	local finished = false
	local invokeOk, invokeResult
	task.spawn(function()
		invokeOk, invokeResult = invokeRemoteFunction(name, table.unpack(packed, 1, packed.n))
		finished = true
	end)
	local deadline = os.clock() + timeout
	while not finished and os.clock() < deadline do
		task.wait(0.05)
	end
	if not finished then
		return false, "timeout (" .. tostring(timeout) .. "s)"
	end
	return invokeOk, invokeResult
end

local function readAuthoritativeRaceTraitWithTimeout()
	if not remotesReady or not statRetrieveRemote then
		return nil, nil, "no stat remote"
	end
	local finished = false
	local race, trait, err
	task.spawn(function()
		local okRace, raceValue = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "Race")
		local okTrait, traitValue = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "SubType")
		if not okRace or not okTrait then
			err = "invoke failed"
		else
			race, trait = raceValue, traitValue
		end
		finished = true
	end)
	local deadline = os.clock() + PROBE_TIMEOUT
	while not finished and os.clock() < deadline do
		task.wait(0.05)
	end
	if not finished then
		return nil, nil, "StatRetrieve timeout"
	end
	return race, trait, err
end

local function summarizeRacePayload(payload)
	if type(payload) == "string" then
		return payload, nil
	end
	if type(payload) == "table" then
		local race = payload.Race or payload.race or payload.selected_Race
		local trait = payload.SubType or payload.Trait or payload.trait or payload.selected_Trait
		return race, trait
	end
	return nil, nil
end

local function readMenuRaceSelection()
	local ok, payload = invokeRemoteFunctionWithTimeout("GetRace", APPLY_TIMEOUT)
	if ok then
		return summarizeRacePayload(payload)
	end
	return nil, nil
end

local function normalizeGetDataPayload(payload)
	if type(payload) == "string" then
		local ok, decoded = pcall(HttpService.JSONDecode, HttpService, payload)
		if ok and type(decoded) == "table" then
			return decoded
		end
	end
	return payload
end

local function readCharacterDataRace(timeoutSeconds)
	local ok, payload = invokeRemoteFunctionWithTimeout("GetData", timeoutSeconds or APPLY_TIMEOUT)
	if not ok then
		return nil, nil
	end
	local data = normalizeGetDataPayload(payload)
	if type(data) ~= "table" then
		return nil, nil
	end
	local char = data.CharacterData or data.characterData
	if type(char) ~= "table" then
		return nil, nil
	end
	local block = char.Race or char.race
	if type(block) == "table" then
		return block.Race or block.race, block.SubType or block.Trait or block.trait
	end
	if type(block) == "string" then
		return block, nil
	end
	return nil, nil
end

local function readSpinCounts()
	local ok, payload = invokeRemoteFunctionWithTimeout("GetSpins", PROBE_TIMEOUT)
	if not ok or type(payload) ~= "table" then
		return 0, 0
	end
	local raceSpins = payload["Race Spins"] or payload.RaceSpins or payload.raceSpins
	local traitSpins = payload["Trait Spins"] or payload.TraitSpins or payload.traitSpins
	return tonumber(raceSpins) or 0, tonumber(traitSpins) or 0
end

local MENU_DATA_WAIT = 22

local function waitForMenuDataReady()
	local deadline = os.clock() + MENU_DATA_WAIT
	local lastGetRaceErr
	local lastGetDataErr
	while os.clock() < deadline do
		tryConnectRemotes()
		local okRace, racePayload = invokeRemoteFunctionWithTimeout("GetRace", PROBE_TIMEOUT)
		if not okRace then
			lastGetRaceErr = racePayload
		end
		local okData, dataPayload = invokeRemoteFunctionWithTimeout("GetData", APPLY_TIMEOUT)
		if not okData then
			lastGetDataErr = dataPayload
		end
		local dataRace, dataTrait = readCharacterDataRace(PROBE_TIMEOUT)
		if dataRace then
			return true, dataRace, dataTrait
		end
		if okRace then
			local getRace = summarizeRacePayload(racePayload)
			if getRace then
				return true, getRace, nil
			end
		end
		task.wait(0.45)
	end
	if lastGetRaceErr then
		appendLog("GetRace not ready: " .. tostring(lastGetRaceErr))
	end
	if lastGetDataErr then
		appendLog("GetData not ready: " .. tostring(lastGetDataErr))
	end
	return false
end

local cachedMenuActions

-- Tables we build carry __gohanOwned so getgc scans never mistake them (or a previous
-- load's copies) for the game's u3 table.
local MENU_ACTION_FALLBACK = {
	__gohanOwned = true,
	-- Sniffed from the game's own race spin: FireServer("Reroll Race", {...}). Trait assumed to match.
	RerollRace = "Reroll Race",
	RerollTrait = "Reroll Trait",
	ChangeSlot = "Change Slot",
}

-- Exact first args learned from sniffing a real in-game spin (survives script reloads).
local learnedActions = environment.__GohanMenuLearnedActions
if type(learnedActions) ~= "table" then
	learnedActions = { __gohanOwned = true }
	environment.__GohanMenuLearnedActions = learnedActions
end

local function makeActionsResult(source, race, trait, changeSlot)
	return {
		__gohanOwned = true,
		__source = source,
		RerollRace = race,
		RerollTrait = trait,
		ChangeSlot = changeSlot,
	}
end

local function isBannedActionsPath(path)
	local lower = string.lower(path)
	if string.find(lower, "kohl", 1, true) then
		return true
	end
	if string.find(lower, "admin source", 1, true) then
		return true
	end
	return false
end

local function normalizeServerAction(actionValue)
	if type(actionValue) == "string" then
		return actionValue
	end
	if type(actionValue) == "table" then
		if type(actionValue._key) == "string" then
			return actionValue._key
		end
		if type(actionValue.Key) == "string" then
			return actionValue.Key
		end
	end
	return actionValue
end

local function scoreActionsTable(result, path)
	if isBannedActionsPath(path) then
		return -1
	end
	if type(result) ~= "table" or not result.RerollRace or not result.RerollTrait then
		return -1
	end
	local score = 0
	if string.find(path, "Title Screen", 1, true) then
		score += 100
	end
	if string.find(path, "Core UI", 1, true) then
		score += 50
	end
	if type(result.RerollRace) == "string" then
		score += 40
	end
	if type(result.RerollTrait) == "string" then
		score += 40
	end
	if type(result.RerollRace) == "table" and type(result.RerollRace._key) == "string" then
		if result.RerollRace._signal ~= nil or rawget(result.RerollRace, "_remote") ~= nil then
			score -= 100
		else
			score += 5
		end
	end
	if string.find(path, "ReplicatedStorage.Modules", 1, true) then
		score += 25
	end
	return score
end

local function findRerollModuleScript()
	local playerGui = localPlayer:FindFirstChild("PlayerGui")
	if not playerGui then
		return nil
	end
	for _, desc in ipairs(playerGui:GetDescendants()) do
		if desc.Name == "RerollController" and desc:IsA("ModuleScript") then
			return desc
		end
	end
	return nil
end

local function getRerollControllerSource()
	local moduleScript = findRerollModuleScript()
	if not moduleScript or type(decompile) ~= "function" then
		return nil
	end
	local ok, source = pcall(decompile, moduleScript)
	if ok and type(source) == "string" then
		return source
	end
	return nil
end

local function isU3ActionsTable(value)
	if type(value) ~= "table" then
		return false
	end
	if rawget(value, "__gohanOwned") or rawget(value, "__source") then
		return false
	end
	if not rawget(value, "RerollRace") or not rawget(value, "RerollTrait") then
		return false
	end
	if not value.RerollRace or not value.RerollTrait then
		return false
	end
	if type(value.RerollRace) == "table" and value.RerollRace._signal ~= nil then
		return false
	end
	return true
end

local function parseU3FromDecompile(source)
	if not source then
		return nil
	end
	local parsed = {}
	for line in string.gmatch(source, "[^\r\n]+") do
		local race = string.match(line, 'RerollRace%s*=%s*"([^"]+)"')
			or string.match(line, "RerollRace%s*=%s*'([^']+)'")
		local trait = string.match(line, 'RerollTrait%s*=%s*"([^"]+)"')
			or string.match(line, "RerollTrait%s*=%s*'([^']+)'")
		local changeSlot = string.match(line, 'ChangeSlot%s*=%s*"([^"]+)"')
			or string.match(line, "ChangeSlot%s*=%s*'([^']+)'")
		if race then
			parsed.RerollRace = race
		end
		if trait then
			parsed.RerollTrait = trait
		end
		if changeSlot then
			parsed.ChangeSlot = changeSlot
		end
	end
	if parsed.RerollRace and parsed.RerollTrait then
		return parsed
	end
	return nil
end

local function captureU3FromRuntime()
	local moduleScript = findRerollModuleScript()
	if not moduleScript then
		return nil
	end
	pcall(require, moduleScript)

	local getUpvalues = debug and debug.getupvalues
	local function scanUpvalues(fn)
		if not getUpvalues then
			return nil
		end
		local ok, upvalues = pcall(getUpvalues, fn)
		if not ok or type(upvalues) ~= "table" then
			return nil
		end
		for _, value in pairs(upvalues) do
			if isU3ActionsTable(value) then
				return value
			end
		end
		return nil
	end

	if type(getgc) ~= "function" then
		return nil
	end
	local okGc, gcList = pcall(getgc, true)
	if not okGc or type(gcList) ~= "table" then
		return nil
	end

	-- Prefer upvalues of RerollController's own functions (spinPrompt closes over u3).
	for _, obj in ipairs(gcList) do
		if type(obj) == "function" then
			local okEnv, env = pcall(getfenv, obj)
			local okScript, owner = false, nil
			if okEnv and type(env) == "table" then
				okScript, owner = pcall(function()
					return env.script
				end)
			end
			if okScript and owner == moduleScript then
				local found = scanUpvalues(obj)
				if found then
					return found, "RerollController closure upvalue"
				end
			end
		end
	end

	for _, obj in ipairs(gcList) do
		if isU3ActionsTable(obj) then
			return obj, "getgc table"
		end
	end

	return nil
end

local function considerModulesFromRerollSource(source, considerFn)
	local modulesRoot = ReplicatedStorage:FindFirstChild("Modules")
	if not modulesRoot or not source then
		return
	end
	for line in string.gmatch(source, "[^\r\n]+") do
		if string.find(line, "require", 1, true) then
			local tail = string.match(line, "Modules%.([%w_%.]+)")
			if tail then
				local node = modulesRoot
				for part in string.gmatch(tail, "[%w_]+") do
					node = node and node:FindFirstChild(part)
				end
				if node and node:IsA("ModuleScript") then
					considerFn(node)
				end
			end
		end
	end
end

local function resolveMenuServerActions()
	if learnedActions.RerollRace ~= nil or learnedActions.RerollTrait ~= nil then
		local fallback = cachedMenuActions or MENU_ACTION_FALLBACK
		return makeActionsResult(
			"sniffed from in-game spin",
			learnedActions.RerollRace ~= nil and learnedActions.RerollRace or fallback.RerollRace,
			learnedActions.RerollTrait ~= nil and learnedActions.RerollTrait or fallback.RerollTrait,
			fallback.ChangeSlot
		)
	end

	if cachedMenuActions then
		return cachedMenuActions
	end

	local runtimeU3, runtimeWhere = captureU3FromRuntime()
	if runtimeU3 then
		cachedMenuActions = makeActionsResult(
			"runtime u3 (" .. tostring(runtimeWhere) .. ")",
			runtimeU3.RerollRace,
			runtimeU3.RerollTrait,
			runtimeU3.ChangeSlot
		)
		return cachedMenuActions
	end

	local rerollSource = getRerollControllerSource()
	local parsedU3 = parseU3FromDecompile(rerollSource)
	if parsedU3 then
		cachedMenuActions = makeActionsResult(
			"RerollController decompile string literals",
			parsedU3.RerollRace,
			parsedU3.RerollTrait,
			parsedU3.ChangeSlot
		)
		return cachedMenuActions
	end

	local bestActions
	local bestPath
	local bestScore = -1

	local function consider(moduleScript)
		if not moduleScript or not moduleScript:IsA("ModuleScript") then
			return
		end
		local path = moduleScript:GetFullName()
		if isBannedActionsPath(path) then
			return
		end
		local ok, result = pcall(require, moduleScript)
		if not ok or type(result) ~= "table" then
			return
		end
		local score = scoreActionsTable(result, path)
		if score > bestScore then
			bestScore = score
			bestActions = result
			bestPath = path
		end
	end

	local playerGui = localPlayer:FindFirstChild("PlayerGui")
	local title = playerGui and playerGui:FindFirstChild("Title Screen")
	local core = title and title:FindFirstChild("Core UI")
	local modulesFolder = core and core:FindFirstChild("Modules")
	if modulesFolder then
		for _, child in ipairs(modulesFolder:GetChildren()) do
			consider(child)
		end
	end

	local gameModules = ReplicatedStorage:FindFirstChild("Modules")
	if gameModules then
		for _, desc in ipairs(gameModules:GetDescendants()) do
			if desc:IsA("ModuleScript") then
				consider(desc)
			end
		end
	end

	local rerollSourceForRequires = getRerollControllerSource()
	considerModulesFromRerollSource(rerollSourceForRequires, consider)

	for _, desc in ipairs(ReplicatedStorage:GetDescendants()) do
		if desc:IsA("ModuleScript") then
			consider(desc)
		end
	end

	if bestActions and bestScore >= 0 then
		cachedMenuActions =
			makeActionsResult(bestPath, bestActions.RerollRace, bestActions.RerollTrait, bestActions.ChangeSlot)
		return cachedMenuActions
	end

	cachedMenuActions = makeActionsResult(
		"fallback strings",
		MENU_ACTION_FALLBACK.RerollRace,
		MENU_ACTION_FALLBACK.RerollTrait,
		MENU_ACTION_FALLBACK.ChangeSlot
	)
	return cachedMenuActions
end

local function fireServerActionArg(actionValue)
	if type(actionValue) == "string" or type(actionValue) == "number" or type(actionValue) == "boolean" then
		return actionValue
	end
	if type(actionValue) == "table" then
		if actionValue._signal ~= nil and type(actionValue._key) == "string" then
			return actionValue._key
		end
		return actionValue
	end
	-- Instances / userdata / nil pass through untouched: the server compares the exact value.
	return actionValue
end

local function logResolvedMenuActions()
	local actions = resolveMenuServerActions()
	appendLog("Menu actions (" .. tostring(actions.__source) .. ")")
	appendLog("  RerollRace raw=" .. formatProbeValue(actions.RerollRace))
	appendLog("  RerollTrait raw=" .. formatProbeValue(actions.RerollTrait))
	appendLog("  RerollRace fireArg=" .. formatProbeValue(fireServerActionArg(actions.RerollRace)))
end

local function readExpectedSlot()
	local ok, slot = invokeRemoteFunctionWithTimeout("GetCurrentSlot", PROBE_TIMEOUT)
	if ok then
		return tonumber(slot) or slot or 1
	end
	return 1
end

local function fireMenuRerollAction(actionValue)
	if actionValue == nil then
		return false, "nil action"
	end
	local fireArg = fireServerActionArg(actionValue)
	local remote = findGameRemote("ServerRemote")
	if not remote then
		return false, "missing ServerRemote"
	end
	local payload = {
		ConfirmWipe = true,
		ExpectedSlot = readExpectedSlot(),
		RequestId = HttpService:GenerateGUID(false),
	}
	appendLog(
		"[Spin API] FireServer("
			.. formatProbeValue(fireArg)
			.. ", ConfirmWipe, slot="
			.. tostring(payload.ExpectedSlot)
			.. ")"
	)
	return pcall(remote.FireServer, remote, fireArg, payload)
end

local SPIN_ANIM_WAIT = 1.25
local readMenuState

local function serverAcceptedSpin(beforeRaceSpins, afterRaceSpins, beforeRace, afterRace)
	if afterRaceSpins < beforeRaceSpins then
		return true, "spin count dropped"
	end
	if beforeRace ~= afterRace then
		return true, "race changed"
	end
	return false, "unchanged (server rejected or no-op)"
end

local function probeSpinBypassExperiments()
	appendLog("=== Spin bypass probe (0 spins = safe; uses real spin if R>0) ===")
	appendLog(
		"Client tricks (fake GetSpins, skip UI) only change what YOU see until the server agrees. "
			.. "Reroll is server-authoritative: inventory + RNG live on the game server."
	)
	tryConnectRemotes()
	local remote = findGameRemote("ServerRemote")
	if not remote then
		appendLog("No ServerRemote — abort.")
		return
	end
	local action = fireServerActionArg(resolveMenuServerActions().RerollRace)
	local slot = readExpectedSlot()
	local beforeRace = select(1, readMenuState())
	local beforeSpins = select(1, readSpinCounts())
	if beforeSpins > 0 then
		appendLog("Race spins > 0 — only firing ONE normal Reroll Race (not all variants).")
	end

	local function tryVariant(label, payload)
		local br = select(1, readMenuState())
		local brs = select(1, readSpinCounts())
		appendLog("[Spin probe] " .. label)
		local ok = pcall(remote.FireServer, remote, action, payload)
		task.wait(SPIN_ANIM_WAIT)
		local ar = select(1, readMenuState())
		local ars = select(1, readSpinCounts())
		local accepted, reason = serverAcceptedSpin(brs, ars, br, ar)
		appendLog(
			string.format(
				"  fire ok=%s %s | R spins %s->%s race %s->%s",
				tostring(ok),
				reason,
				tostring(brs),
				tostring(ars),
				tostring(br),
				tostring(ar)
			)
		)
		return accepted
	end

	local guid = function()
		return HttpService:GenerateGUID(false)
	end

	if beforeSpins <= 0 then
		tryVariant("normal", {
			ConfirmWipe = true,
			ExpectedSlot = slot,
			RequestId = guid(),
		})
		tryVariant("ConfirmWipe=false", {
			ConfirmWipe = false,
			ExpectedSlot = slot,
			RequestId = guid(),
		})
		tryVariant("no ExpectedSlot", {
			ConfirmWipe = true,
			RequestId = guid(),
		})
		tryVariant("SkipCost/FreeSpin guess", {
			ConfirmWipe = true,
			ExpectedSlot = slot,
			RequestId = guid(),
			SkipCost = true,
			FreeSpin = true,
		})
	else
		tryVariant("normal (you had spins)", {
			ConfirmWipe = true,
			ExpectedSlot = slot,
			RequestId = guid(),
		})
	end

	appendLog("--- GetSpins grant guesses (usually read-only) ---")
	local grantCalls = {
		{ "GetSpins", "Add", "Race", 1 },
		{ "GetSpins", "Grant", "Race", 1 },
		{ "GetSpins", "Set", "Race Spins", 99 },
	}
	for _, call in ipairs(grantCalls) do
		local name = call[1]
		local ok, result = invokeRemoteFunctionWithTimeout(name, PROBE_TIMEOUT, select(2, table.unpack(call)))
		local argText = table.concat(call, ", ")
		appendLog(argText .. " ok=" .. tostring(ok) .. " -> " .. formatProbeValue(result))
	end
	local afterGrantSpins = select(1, readSpinCounts())
	appendLog("GetSpins after grant guesses: R=" .. tostring(afterGrantSpins))

	local moduleScript = findRerollModuleScript()
	if moduleScript then
		appendLog("--- RerollController exports (game spin path) ---")
		local okReq, ctrl = pcall(require, moduleScript)
		if okReq and type(ctrl) == "table" then
			for key, value in pairs(ctrl) do
				if type(value) == "function" then
					local lower = string.lower(tostring(key))
					if string.find(lower, "spin", 1, true) or string.find(lower, "reroll", 1, true) then
						appendLog("  fn " .. tostring(key))
					end
				end
			end
		else
			appendLog("  require failed: " .. tostring(ctrl))
		end
	end

	appendLog("=== Spin bypass probe end ===")
	appendLog("If every variant says unchanged @ 0 spins: no client trick — use Earth gohan_dev set, or earn spins.")
end

local function menuRaceSpinOnce()
	return fireMenuRerollAction(resolveMenuServerActions().RerollRace)
end

local function menuTraitSpinOnce()
	return fireMenuRerollAction(resolveMenuServerActions().RerollTrait)
end

readMenuState = function()
	local getRace, _ = readMenuRaceSelection()
	local dataRace, dataTrait = readCharacterDataRace(PROBE_TIMEOUT)
	local race = dataRace or getRace
	local trait = dataTrait
	return race, trait, getRace, dataRace, dataTrait
end

local function menuStateMatchesTarget(targetRace, targetTrait)
	local race, trait = readMenuState()
	if race ~= targetRace then
		return false
	end
	if targetTrait and trait and trait ~= targetTrait then
		return false
	end
	if targetTrait and not trait then
		return false
	end
	return true
end

local function logMenuSnapshot(prefix)
	local race, trait, getRace, dataRace, dataTrait = readMenuState()
	local raceSpins, traitSpins = readSpinCounts()
	appendLog(
		string.format(
			"%s GetRace=%s GetData=%s/%s combined=%s/%s spins R=%s T=%s",
			prefix,
			tostring(getRace),
			tostring(dataRace),
			tostring(dataTrait),
			tostring(race),
			tostring(trait),
			tostring(raceSpins),
			tostring(traitSpins)
		)
	)
	return race, trait, raceSpins, traitSpins
end

local READ_ONLY_REMOTES = {
	GetData = true,
	GetSubprofileData = true,
}

local function isMutationCapture(capture)
	if capture.method == "FireServer" then
		return true
	end
	if capture.args.n > 0 then
		return true
	end
	return false
end

local function isReadOnlyCapture(capture)
	if READ_ONLY_REMOTES[capture.name] then
		return true
	end
	if not isMutationCapture(capture) then
		return true
	end
	return false
end

local sniffSpinBaseline = nil
local sniffGettersSeen = {}

local function isSpinPayload(payload)
	return type(payload) == "table" and (payload.ConfirmWipe ~= nil or payload.ExpectedSlot ~= nil)
end

local function learnSpinAction(firstArg)
	local beforeRace, beforeTrait = sniffSpinBaseline and sniffSpinBaseline[1], sniffSpinBaseline and sniffSpinBaseline[2]
	task.wait(1.5)
	local raceSpins, traitSpins = readSpinCounts()
	sniffSpinBaseline = { raceSpins, traitSpins }
	local shown = formatProbeValue(firstArg) .. " (" .. typeof(firstArg) .. ")"
	if beforeRace and raceSpins < beforeRace then
		learnedActions.RerollRace = firstArg
		appendLog("[Learn] RerollRace = " .. shown .. " (race spins " .. beforeRace .. "->" .. raceSpins .. ")")
	elseif beforeTrait and traitSpins < beforeTrait then
		learnedActions.RerollTrait = firstArg
		appendLog("[Learn] RerollTrait = " .. shown .. " (trait spins " .. beforeTrait .. "->" .. traitSpins .. ")")
	else
		appendLog("[Learn] spin fired with " .. shown .. " but no spin count dropped - not learned")
	end
end

local function installRemoteSniffer()
	if snifferInstalled then
		return true
	end
	if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then
		return false
	end
	local oldNamecall
	local function onNamecall(self, ...)
		local method = getnamecallmethod()
		-- No namecalls (self:IsA / :IsDescendantOf) before forwarding: each one overwrites the
		-- pending namecall method, so oldNamecall would dispatch the wrong method on the game's call.
		if sniffActive and (method == "FireServer" or method == "InvokeServer") and typeof(self) == "Instance" then
			local packed = table.pack(...)
			task.defer(function()
				if not (self:IsA("RemoteEvent") or self:IsA("RemoteFunction")) then
					return
				end
				if self:IsDescendantOf(ReplicatedStorage) then
					rememberRemote(self)
					local parts = {}
					for i = 1, packed.n do
						parts[i] = formatProbeValue(packed[i])
					end
					local argText = table.concat(parts, " | ")
					if argText == "" then
						argText = "(no args)"
					end
					local capture = {
						method = method,
						name = self.Name,
						remote = self,
						path = self:GetFullName(),
						args = packed,
					}
					if isMutationCapture(capture) then
						table.insert(remoteCaptures, capture)
						appendLog("[Sniff] " .. method .. " " .. self.Name .. " " .. argText)
						if self.Name == "ServerRemote" and method == "FireServer" and isSpinPayload(packed[2]) then
							task.spawn(learnSpinAction, packed[1])
						end
					elseif not sniffGettersSeen[self.Name] then
						sniffGettersSeen[self.Name] = true
						appendLog("[Sniff getter] " .. method .. " " .. self.Name .. " " .. argText .. " (further calls hidden)")
					end
				end
			end)
		end
		return oldNamecall(self, ...)
	end
	if type(newcclosure) == "function" then
		onNamecall = newcclosure(onNamecall)
	end
	oldNamecall = hookmetamethod(game, "__namecall", onNamecall)
	snifferOldNamecall = oldNamecall
	snifferInstalled = true
	return true
end

local function uninstallRemoteSniffer()
	if not snifferInstalled or not snifferOldNamecall then
		return
	end
	if type(restorehookmetamethod) == "function" then
		pcall(restorehookmetamethod, game, "__namecall", snifferOldNamecall)
	elseif type(hookmetamethod) == "function" then
		pcall(hookmetamethod, game, "__namecall", snifferOldNamecall)
	end
	snifferInstalled = false
	snifferOldNamecall = nil
end

local function sniffedCaptureSummary()
	local hardcodeCount = 0
	local otherCount = 0
	for _, capture in ipairs(remoteCaptures) do
		if not isMutationCapture(capture) then
			continue
		end
		if capture.name == "ServerRemote" and capture.method == "FireServer" then
			local payload = capture.args[2]
			if type(payload) == "table" and payload.Action == "HardcodePlayer" then
				hardcodeCount += 1
			else
				otherCount += 1
			end
		else
			otherCount += 1
		end
	end
	return hardcodeCount, otherCount
end

local function setSniffActive(active)
	if active and not installRemoteSniffer() then
		appendLog("Sniffer needs hookmetamethod (Volt should support this).")
		setStatus("Sniffer unavailable in this executor.", colors.Warning)
		return false
	end
	if active then
		sniffSpinBaseline = { readSpinCounts() }
		appendLog("Spin baseline R=" .. tostring(sniffSpinBaseline[1]) .. " T=" .. tostring(sniffSpinBaseline[2]))
	end
	sniffActive = active
	sniffButton.Text = sniffActive and "Sniff ON - spin in game" or "Sniff spin (30s)"
	if sniffActive then
		table.clear(remoteCaptures)
		table.clear(sniffGettersSeen)
		appendLog("=== Sniff ON: press SPIN (costs a spin). Panel open = Get* getters only (ignored). ===")
		task.delay(30, function()
			if sniffActive then
				sniffActive = false
				sniffButton.Text = "Sniff spin (30s)"
				appendLog(
					"=== Sniff off - "
						.. tostring(#remoteCaptures)
						.. " mutation capture(s) for Apply replay ==="
				)
				if #remoteCaptures == 0 then
					appendLog("No mutations seen. Sniff again and press the actual Spin button.")
				else
					local hardcodeCount, otherCount = sniffedCaptureSummary()
					if hardcodeCount > 0 and otherCount == 0 then
						appendLog(
							"Only HardcodePlayer captured - usually from this panel, not game spin. Sniff again: Spin in-game only, no Apply."
						)
					end
				end
			end
		end)
	else
		appendLog("=== Sniff off - " .. tostring(#remoteCaptures) .. " mutation capture(s) ===")
	end
	return true
end

local function replayRemoteCapture(capture)
	local packed = capture.args
	if type(packed[2]) == "table" and packed[2].RequestId ~= nil then
		local fresh = table.clone(packed[2])
		fresh.RequestId = HttpService:GenerateGUID(false)
		if fresh.ExpectedSlot ~= nil then
			fresh.ExpectedSlot = readExpectedSlot()
		end
		packed = table.clone(packed)
		packed[2] = fresh
	end
	local remote = capture.remote
	if not remote or not remote.Parent then
		remote = findGameRemote(capture.name)
	end
	if capture.method == "FireServer" then
		if remote and remote:IsA("RemoteEvent") then
			return fireRemoteInstance(remote, table.unpack(packed, 1, packed.n))
		end
		return fireRemoteEvent(capture.name, table.unpack(packed, 1, packed.n))
	end
	if remote and remote:IsA("RemoteFunction") then
		local finished = false
		local invokeOk, invokeResult
		task.spawn(function()
			invokeOk, invokeResult = invokeRemoteInstance(remote, table.unpack(packed, 1, packed.n))
			finished = true
		end)
		local deadline = os.clock() + APPLY_TIMEOUT
		while not finished and os.clock() < deadline do
			task.wait(0.05)
		end
		if not finished then
			return false, "timeout"
		end
		return invokeOk, invokeResult
	end
	return invokeRemoteFunctionWithTimeout(capture.name, APPLY_TIMEOUT, table.unpack(packed, 1, packed.n))
end

local function isHubHardcodeCapture(capture)
	if capture.name ~= "ServerRemote" or capture.method ~= "FireServer" then
		return false
	end
	local payload = capture.args[2]
	return type(payload) == "table" and payload.Action == "HardcodePlayer"
end

local function tryReplayCaptures(targetRace, targetTrait, beforeDataRace)
	if #remoteCaptures == 0 then
		appendLog("[Replay] no mutation captures - Sniff + press in-game Spin first.")
		return nil
	end
	local seen = {}
	for _, capture in ipairs(remoteCaptures) do
		if isHubHardcodeCapture(capture) then
			continue
		end
		if not isReadOnlyCapture(capture) then
			local key = capture.method .. ":" .. capture.name .. ":" .. formatProbeValue(capture.args)
			if not seen[key] then
				seen[key] = true
				local ok, result = replayRemoteCapture(capture)
				appendLog(
					"[Replay] "
						.. capture.name
						.. (capture.path and (" @" .. capture.path) or "")
						.. " ok="
						.. tostring(ok)
						.. " -> "
						.. formatProbeValue(result)
				)
				task.wait(0.55)
				if menuStateMatchesTarget(targetRace, targetTrait) then
					return "replay " .. capture.name
				end
				local dataRace = select(1, readCharacterDataRace(PROBE_TIMEOUT))
				if beforeDataRace and dataRace and dataRace ~= beforeDataRace then
					appendLog("[Replay] GetData race now " .. tostring(dataRace))
				end
			end
		end
	end
	return nil
end

local function copyPayloadTable(payload)
	if type(payload) ~= "table" then
		return payload
	end
	local copy = {}
	for key, value in pairs(payload) do
		copy[key] = value
	end
	return copy
end

local function tryApplySniffedServerRemote(targetRace, targetTrait)
	for index = #remoteCaptures, 1, -1 do
		local capture = remoteCaptures[index]
		if capture.name ~= "ServerRemote" or capture.method ~= "FireServer" then
			continue
		end
		local packed = capture.args
		local payload = packed[2]
		if type(payload) ~= "table" then
			local ok = replayRemoteCapture(capture)
			appendLog("[Apply sniff] exact ServerRemote ok=" .. tostring(ok))
			task.wait(0.5)
			if menuStateMatchesTarget(targetRace, targetTrait) then
				return "ServerRemote exact"
			end
		else
			local copy = copyPayloadTable(payload)
			if copy.Action == "HardcodePlayer" or copy.Module == "DragonballManager" then
				copy.selected_Race = targetRace
				copy.selected_Trait = targetTrait
				copy.change_Race = true
				copy.change_Trait = true
			end
			local remote = capture.remote or findGameRemote("ServerRemote")
			if remote then
				local ok = pcall(remote.FireServer, remote, packed[1], copy)
				appendLog("[Apply sniff] ServerRemote " .. formatProbeValue(copy) .. " ok=" .. tostring(ok))
				task.wait(0.5)
				if menuStateMatchesTarget(targetRace, targetTrait) then
					return "ServerRemote template"
				end
			end
		end
	end
	return nil
end

local function menuStateChanged(beforeRace, beforeTrait, beforeRaceSpins, beforeTraitSpins)
	local race, trait = readMenuState()
	local raceSpins, traitSpins = readSpinCounts()
	if beforeRace and race and race ~= beforeRace then
		return true
	end
	if beforeTrait and trait and trait ~= beforeTrait then
		return true
	end
	if beforeRaceSpins and raceSpins < beforeRaceSpins then
		return true
	end
	if beforeTraitSpins and traitSpins < beforeTraitSpins then
		return true
	end
	return false
end

local function runAttemptList(labelPrefix, attempts, race, trait, beforeRace, beforeTrait, beforeRaceSpins, beforeTraitSpins)
	for _, attempt in ipairs(attempts) do
		local ok, result = attempt.run()
		appendLog(labelPrefix .. attempt.label .. " ok=" .. tostring(ok) .. " -> " .. formatProbeValue(result))
		task.wait(SPIN_ANIM_WAIT)
		if race and trait and menuStateMatchesTarget(race, trait) then
			return attempt.label
		end
		if menuStateChanged(beforeRace, beforeTrait, beforeRaceSpins, beforeTraitSpins) then
			return attempt.label .. " (state changed)"
		end
		if type(result) == "table" and (result.Race or result.race) then
			local rolled = result.Race or result.race
			if race and rolled == race then
				return attempt.label .. " (result race)"
			end
		end
	end
	return nil
end

local function buildSetAttempts(race, trait)
	local remote = findGameRemote("ServerRemote")
	if not remote then
		return {}
	end
	local slot = readExpectedSlot()
	local attempts = {}

	local function add(label, fireFn)
		table.insert(attempts, { label = label, run = fireFn })
	end

	add("HardcodePlayer (menu usually ignores)", function()
		return pcall(remote.FireServer, remote, nil, {
			Module = "DragonballManager",
			Action = "HardcodePlayer",
			change_Race = true,
			change_Trait = true,
			selected_Race = race,
			selected_Trait = trait,
		})
	end)

	local setPayload = {
		Race = race,
		SubType = trait,
		Trait = trait,
		selected_Race = race,
		selected_Trait = trait,
		ExpectedSlot = slot,
	}
	local setActions = {
		"Set Race",
		"SetRace",
		"Select Race",
		"Apply Race",
		"Change Race",
	}
	for _, action in ipairs(setActions) do
		add("ServerRemote " .. action .. " + slot", function()
			return pcall(remote.FireServer, remote, action, setPayload)
		end)
		add("ServerRemote " .. action .. " (no ConfirmWipe)", function()
			local payload = copyPayloadTable(setPayload)
			payload.ConfirmWipe = false
			return pcall(remote.FireServer, remote, action, payload)
		end)
	end

	add("ServerRemote nil SetRace table", function()
		return pcall(remote.FireServer, remote, nil, {
			Module = "DragonballManager",
			Action = "SetRace",
			selected_Race = race,
			selected_Trait = trait,
			ExpectedSlot = slot,
		})
	end)

	add("SlotRemote SetRace", function()
		return fireRemoteEvent("SlotRemote", "SetRace", race, trait)
	end)
	add("SlotRemote table SetRace", function()
		return fireRemoteEvent("SlotRemote", {
			Action = "SetRace",
			Race = race,
			SubType = trait,
			Trait = trait,
			ExpectedSlot = slot,
		})
	end)
	add("StatChangeRemote table", function()
		return fireRemoteEvent("StatChangeRemote", setPayload)
	end)

	return attempts
end

local function buildRaceSpinAttempts()
	return {
		{
			label = "ServerRemote RerollRace",
			run = function()
				return menuRaceSpinOnce()
			end,
		},
	}
end

local function buildTraitSpinAttempts()
	return {
		{
			label = "ServerRemote RerollTrait",
			run = function()
				return menuTraitSpinOnce()
			end,
		},
	}
end

local function buildServerRemoteAttempts(_race, _trait)
	return {}
end

local function tryDirectSetRaceTrait(race, trait, beforeRace, beforeTrait, beforeRaceSpins, beforeTraitSpins)
	local attempts = buildSetAttempts(race, trait)
	return runAttemptList("[Apply] ", attempts, race, trait, beforeRace, beforeTrait, beforeRaceSpins, beforeTraitSpins)
end

local function tryDirectSetTraitOnly(trait, beforeRace, beforeTrait, beforeRaceSpins, beforeTraitSpins)
	local attempts = {
		{
			label = "GetSpins(Set,Trait)",
			run = function()
				return invokeRemoteFunctionWithTimeout("GetSpins", APPLY_TIMEOUT, "Set", "Trait", trait)
			end,
		},
		{
			label = "SlotRemote SetTrait",
			run = function()
				return fireRemoteEvent("SlotRemote", "SetTrait", trait)
			end,
		},
	}
	return runAttemptList("[Apply trait] ", attempts, nil, trait, beforeRace, beforeTrait, beforeRaceSpins, beforeTraitSpins)
end

local function spinUntilRace(targetRace, budget, beforeRace, beforeTrait, beforeRaceSpins, beforeTraitSpins)
	local limit = math.min(budget or 0, MAX_AUTO_SPINS)
	if limit <= 0 then
		appendLog("[Race spin] skipped - 0 Race Spins reported")
		return false
	end
	local attempts = buildRaceSpinAttempts()
	for i = 1, limit do
		local br, bt, brs, bts = readMenuState()
		brs, bts = readSpinCounts()
		local via = runAttemptList("[Race spin #" .. tostring(i) .. "] ", attempts, targetRace, nil, br, bt, brs, bts)
		if via then
			local race = select(1, readMenuState())
			if race == targetRace then
				appendLog("[Race spin] hit " .. targetRace .. " via " .. via)
				return true
			end
			appendLog("[Race spin] changed state but race is " .. tostring(race))
		end
	end
	return false
end

local function spinUntilTrait(targetTrait, budget, beforeRace, beforeTrait, beforeRaceSpins, beforeTraitSpins)
	local limit = math.min(budget or 0, MAX_AUTO_SPINS)
	if limit <= 0 then
		appendLog("[Trait spin] skipped - 0 Trait Spins reported")
		return false
	end
	local attempts = buildTraitSpinAttempts()
	for i = 1, limit do
		local br, bt, brs, bts = readMenuState()
		brs, bts = readSpinCounts()
		local via = runAttemptList("[Trait spin #" .. tostring(i) .. "] ", attempts, nil, targetTrait, br, bt, brs, bts)
		if via then
			local _, trait = readMenuState()
			if trait == targetTrait then
				return true
			end
		end
	end
	return false
end

local function tryHardcodePlayerFallback(race, trait)
	if not serverRemote then
		return false
	end
	local ok = pcall(function()
		serverRemote:FireServer(nil, {
			Module = "DragonballManager",
			Action = "HardcodePlayer",
			change_Race = true,
			change_Trait = true,
			selected_Race = race,
			selected_Trait = trait,
		})
	end)
	appendLog("[Apply] HardcodePlayer fallback ok=" .. tostring(ok))
	task.wait(0.5)
	return ok and menuStateMatchesTarget(race, trait)
end

local function rollRaceSpinOnce()
	if busy then
		return
	end
	if not tryConnectRemotes() then
		setStatus("Remotes not ready.", colors.Warning)
		return
	end
	busy = true
	task.spawn(function()
		local beforeRace = select(1, readMenuState())
		local beforeR = select(1, readSpinCounts())
		local ok = menuRaceSpinOnce()
		task.wait(SPIN_ANIM_WAIT)
		local afterR = select(1, readSpinCounts())
		local race = select(1, readMenuState())
		local accepted = afterR < beforeR or race ~= beforeRace
		logMenuSnapshot("[Roll race]")
		appendLog(
			"[Roll race] ok="
				.. tostring(ok)
				.. " accepted="
				.. tostring(accepted)
				.. " spins R="
				.. tostring(beforeR)
				.. "->"
				.. tostring(afterR)
				.. " race="
				.. tostring(beforeRace)
				.. "->"
				.. tostring(race)
		)
		if beforeR <= 0 and afterR <= 0 then
			appendLog("[Roll race] Server did not spend/grant a spin (R still 0). Run probe for bypass tests.")
		end
		setStatus(
			accepted and ("Rolled race spin - now " .. tostring(race)) or "Spin rejected (0 spins?) — Earth set or earn spins.",
			accepted and colors.Success or colors.Warning
		)
		busy = false
	end)
end

local function rollTraitSpinOnce()
	if busy then
		return
	end
	if not tryConnectRemotes() then
		setStatus("Remotes not ready.", colors.Warning)
		return
	end
	busy = true
	task.spawn(function()
		local _, beforeT = readSpinCounts()
		local ok = menuTraitSpinOnce()
		task.wait(SPIN_ANIM_WAIT)
		local _, afterT = readSpinCounts()
		local _, trait = readMenuState()
		appendLog("[Roll trait] ok=" .. tostring(ok) .. " spins T=" .. tostring(beforeT) .. "->" .. tostring(afterT) .. " trait=" .. tostring(trait))
		setStatus("Rolled trait spin - now " .. tostring(trait), colors.Success)
		busy = false
	end)
end

local function applySelection()
	if busy then
		return
	end
	if not selectedRace or not selectedTrait then
		setStatus("Select both race and trait.", colors.Warning)
		return
	end
	if not tryConnectRemotes() then
		setStatus("Remotes not ready on this place yet.", colors.Warning)
		return
	end

	busy = true
	applyButton.Text = "Setting..."
	task.spawn(function()
		appendLog("Waiting for GetRace/GetData (open Race Reroll on title screen if this hangs)...")
		local ready = waitForMenuDataReady()
		if not ready then
			setStatus("Menu slot not loaded - open Race Reroll UI, wait for race text, then Set again.", colors.Warning)
			busy = false
			applyButton.Text = "Set race + trait"
			return
		end

		local targetRace, targetTrait = selectedRace, selectedTrait
		local beforeRace, beforeTrait, raceSpins, traitSpins = logMenuSnapshot("Before")
		local _, beforeDataRace = readCharacterDataRace(PROBE_TIMEOUT)

		if menuStateMatchesTarget(targetRace, targetTrait) then
			setStatus(string.format("Already %s / %s on menu data.", tostring(beforeRace), tostring(beforeTrait)), colors.Success)
			busy = false
			applyButton.Text = "Set race + trait"
			return
		end

		appendLog("Set mode: direct apply only (no spin). Reroll Race is RNG, not pick-a-race.")

		local via = tryReplayCaptures(targetRace, targetTrait, beforeDataRace)
		if via and menuStateMatchesTarget(targetRace, targetTrait) then
			logMenuSnapshot("After " .. via)
			setStatus("Set via " .. via, colors.Success)
			busy = false
			applyButton.Text = "Set race + trait"
			return
		end

		via = tryApplySniffedServerRemote(targetRace, targetTrait)
		if via and menuStateMatchesTarget(targetRace, targetTrait) then
			logMenuSnapshot("After " .. via)
			setStatus("Set via " .. via, colors.Success)
			busy = false
			applyButton.Text = "Set race + trait"
			return
		end

		if not isCharacterMenuPlace() then
			via = tryDirectSetRaceTrait(
				targetRace,
				targetTrait,
				beforeRace,
				beforeTrait,
				raceSpins,
				traitSpins
			)
			if via and menuStateMatchesTarget(targetRace, targetTrait) then
				logMenuSnapshot("After " .. via)
				setStatus("Set via " .. via, colors.Success)
				busy = false
				applyButton.Text = "Set race + trait"
				return
			end
		else
			appendLog(
				"[Apply] Menu place: no direct-set API (HardcodePlayer/Set Race are ignored). "
					.. "Use gohan_dev Profile Editor on Earth, or Roll race (RNG, needs spins)."
			)
			if raceSpins <= 0 then
				appendLog("[Apply] Race spins = 0 — in-game Roll race will not grant a pick either.")
			end
		end

		local finalRace, finalTrait = readMenuState()
		logMenuSnapshot("Failed")
		setStatus(
			string.format(
				"Menu did not set %s / %s (still %s / %s). Use gohan_dev Profile Editor on Earth for direct set; Roll race/trait uses spins (RNG).",
				targetRace,
				targetTrait,
				tostring(finalRace),
				tostring(finalTrait)
			),
			colors.Danger
		)
		busy = false
		applyButton.Text = "Set race + trait"
	end)
end

local probeBusy = false

local function splitSourceLines(source)
	local lines = {}
	for line in string.gmatch(source, "([^\r\n]+)") do
		table.insert(lines, line)
	end
	return lines
end

local function dumpRerollController()
	appendLog("=== RerollController dump ===")
	tryConnectRemotes()
	local moduleScript = findRerollModuleScript()
	if not moduleScript then
		appendLog("Not found - load the title screen in PlayerGui first.")
		return
	end
	appendLog(moduleScript:GetFullName())
	local raceSpins, traitSpins = readSpinCounts()
	appendLog("GetSpins: R=" .. tostring(raceSpins) .. " T=" .. tostring(traitSpins))
	if raceSpins == 0 then
		appendLog(
			"0 race spins: spin click often gets nil from server -> RefreshDisplay(175) Argument 1 nil (game UI bug)."
		)
	end
	local source
	if type(decompile) == "function" then
		local ok, result = pcall(decompile, moduleScript)
		if ok and type(result) == "string" then
			source = result
		end
	end
	if not source then
		appendLog("decompile() unavailable - paste Volt stack line numbers to chat.")
		appendLog("=== end dump ===")
		return
	end
	local lines = splitSourceLines(source)
	for i = 165, math.min(185, #lines) do
		appendLog(string.format("%4d| %s", i, lines[i]))
	end
	for i = 485, math.min(505, #lines) do
		appendLog(string.format("%4d| %s", i, lines[i]))
	end
	appendLog("--- InvokeServer / FireServer / Spin ---")
	for i, line in ipairs(lines) do
		if
			string.find(line, "InvokeServer", 1, true)
			or string.find(line, "FireServer", 1, true)
			or string.find(line, "RefreshDisplay", 1, true)
			or string.find(line, "Reroll", 1, true)
		then
			appendLog(string.format("%4d| %s", i, line))
		end
	end
	appendLog("=== end dump (copy to chat) ===")
	cachedMenuActions = nil
	local modulesFolder = localPlayer:FindFirstChild("PlayerGui")
		and localPlayer.PlayerGui:FindFirstChild("Title Screen")
		and localPlayer.PlayerGui["Title Screen"]:FindFirstChild("Core UI")
		and localPlayer.PlayerGui["Title Screen"]["Core UI"]:FindFirstChild("Modules")
	if modulesFolder then
		appendLog("Title Screen Modules:")
		for _, child in ipairs(modulesFolder:GetChildren()) do
			appendLog("  " .. child.Name)
		end
	end
	if source then
		appendLog("--- RerollController require(Modules.*) lines ---")
		for line in string.gmatch(source, "[^\r\n]+") do
			if string.find(line, "require", 1, true) and string.find(line, "Modules", 1, true) then
				appendLog(line)
			end
			if string.find(line, "u3", 1, true) and string.find(line, "require", 1, true) then
				appendLog("u3: " .. line)
			end
		end
	end
	appendLog("--- ReplicatedStorage modules exporting RerollRace ---")
	for _, desc in ipairs(ReplicatedStorage:GetDescendants()) do
		if desc:IsA("ModuleScript") and not isBannedActionsPath(desc:GetFullName()) then
			local ok, exported = pcall(require, desc)
			if ok and type(exported) == "table" and exported.RerollRace and exported.RerollTrait then
				appendLog(
					desc:GetFullName()
						.. " raceKey="
						.. formatProbeValue(normalizeServerAction(exported.RerollRace))
				)
			end
		end
	end
	appendLog("(empty list = u3 is inside RerollController, not a Module export)")
	cachedMenuActions = nil
	appendLog(
		"Learned from sniff: RerollRace="
			.. formatProbeValue(learnedActions.RerollRace)
			.. " RerollTrait="
			.. formatProbeValue(learnedActions.RerollTrait)
	)
	local runtimeU3, runtimeWhere = captureU3FromRuntime()
	if runtimeU3 then
		appendLog("Runtime u3 capture: OK via " .. tostring(runtimeWhere))
		appendLog("  RerollRace=" .. formatProbeValue(runtimeU3.RerollRace) .. " (" .. typeof(runtimeU3.RerollRace) .. ")")
		appendLog("  RerollTrait=" .. formatProbeValue(runtimeU3.RerollTrait) .. " (" .. typeof(runtimeU3.RerollTrait) .. ")")
	else
		appendLog("Runtime u3 capture: failed (require RerollController loaded first?)")
	end
	local parsed = parseU3FromDecompile(source)
	if parsed then
		appendLog("Decompile literal parse: " .. formatProbeValue(parsed.RerollRace))
	end
	logResolvedMenuActions()
end

local function probeRemotes()
	if probeBusy then
		appendLog("Probe already running...")
		return
	end
	probeBusy = true
	probeButton.Text = "Probing..."
	task.spawn(function()
		appendLog("=== Probe start ===")
		appendLog("PlaceId " .. tostring(game.PlaceId))
		appendLog(
			"PlayerStats: "
				.. (localPlayer:FindFirstChild("PlayerStats") and "yes" or "no (normal on menu before slot)")
		)
		local folder = ReplicatedStorage:FindFirstChild("Remotes")
		if not folder then
			appendLog("No Remotes folder.")
			setStatus("No Remotes folder.", colors.Danger)
			probeBusy = false
			probeButton.Text = "Run probe"
			return
		end
		appendLog("Remotes: " .. tostring(#folder:GetChildren()) .. " entries")
		for _, child in ipairs(folder:GetChildren()) do
			appendLog("  " .. child.ClassName .. " " .. child.Name)
		end
		tryConnectRemotes()
		local statRace, statTrait, statErr = readAuthoritativeRaceTraitWithTimeout()
		if statErr then
			appendLog("StatRetrieve: " .. statErr)
		else
			appendLog("StatRetrieve Race/SubType: " .. tostring(statRace) .. " / " .. tostring(statTrait))
		end
		local probes = {
			{ "GetRace" },
			{ "GetSpins" },
			{ "GetCurrentPity" },
			{ "GetCurrentSlot" },
			{ "GetSubprofileData" },
			{ "GetData" },
		}
		for _, args in ipairs(probes) do
			local name = args[1]
			local ok, result = invokeRemoteFunctionWithTimeout(name, PROBE_TIMEOUT, select(2, table.unpack(args)))
			appendLog(name .. " ok=" .. tostring(ok) .. " -> " .. formatProbeValue(result))
		end
		local dataRace, dataTrait = readCharacterDataRace(APPLY_TIMEOUT)
		appendLog("GetData CharacterData.Race: " .. tostring(dataRace) .. " / " .. tostring(dataTrait))
		local menuRace, menuTrait = readMenuRaceSelection()
		appendLog("Parsed GetRace: " .. tostring(menuRace) .. " / " .. tostring(menuTrait))
		if isCharacterMenuPlace() then
			probeSpinBypassExperiments()
		end
		appendLog("=== Probe end (scroll log if cut off) ===")
		setStatus("Probe done - scroll log box for GetRace/GetSpins lines.", colors.Success)
		probeBusy = false
		probeButton.Text = "Run probe"
	end)
end

