function configStore.GetFunction(name)
	local callback = environment[name]
	if type(callback) == "function" then
		return callback
	end
	return nil
end

function configStore.EnsureFolders()
	local isfolder = configStore.GetFunction("isfolder")
	local makefolder = configStore.GetFunction("makefolder")
	if not isfolder or not makefolder then
		return false
	end
	if not isfolder(configStore.Root) then
		makefolder(configStore.Root)
	end
	if not isfolder(configStore.ConfigFolder) then
		makefolder(configStore.ConfigFolder)
	end
	return true
end

function configStore.NormalizeName(name)
	if type(name) ~= "string" then
		return nil
	end
	local normalized = name:gsub("%.json$", ""):gsub("[^%w_%-]", ""):sub(1, 40)
	return normalized ~= "" and normalized or nil
end

function configStore.PathFor(name)
	local normalized = configStore.NormalizeName(name)
	return normalized and (configStore.ConfigFolder .. "/" .. normalized .. ".json") or nil
end

function configStore.ListNames()
	local listfiles = configStore.GetFunction("listfiles")
	if not listfiles or not configStore.EnsureFolders() then
		return {}
	end
	local ok, files = pcall(listfiles, configStore.ConfigFolder)
	local names = {}
	if ok and type(files) == "table" then
		for _, path in ipairs(files) do
			local name = type(path) == "string" and path:match("([^/\\]+)%.json$") or nil
			name = configStore.NormalizeName(name)
			if name then
				table.insert(names, name)
			end
		end
	end
	table.sort(names)
	return names
end

function configStore.Read(name)
	local readfile = configStore.GetFunction("readfile")
	local isfile = configStore.GetFunction("isfile")
	local path = configStore.PathFor(name)
	if not readfile or not isfile or not path or not isfile(path) then
		return nil
	end
	local ok, body = pcall(readfile, path)
	if not ok or type(body) ~= "string" then
		return nil
	end
	local decodedOk, decoded = pcall(HttpService.JSONDecode, HttpService, body)
	return decodedOk and type(decoded) == "table" and decoded or nil
end

function configStore.Write(name, data, overwrite)
	local writefile = configStore.GetFunction("writefile")
	local isfile = configStore.GetFunction("isfile")
	local path = configStore.PathFor(name)
	if not writefile or not isfile or not path or not configStore.EnsureFolders() then
		return false, "Executor filesystem APIs are unavailable."
	end
	if isfile(path) and not overwrite then
		return false, "That config already exists; use Save to overwrite it."
	end
	local encodeOk, body = pcall(HttpService.JSONEncode, HttpService, data)
	if not encodeOk then
		return false, "Config serialization failed."
	end
	local ok = pcall(writefile, path, body)
	if ok then
		return true
	end
	return false, "Could not write the config file."
end

function configStore.Delete(name)
	local delfile = configStore.GetFunction("delfile")
	local isfile = configStore.GetFunction("isfile")
	local path = configStore.PathFor(name)
	if not delfile or not isfile or not path or not isfile(path) then
		return false
	end
	return pcall(delfile, path)
end

function configStore.ReadAutoload()
	local readfile = configStore.GetFunction("readfile")
	local isfile = configStore.GetFunction("isfile")
	if not readfile or not isfile or not isfile(configStore.AutoloadFile) then
		return nil
	end
	local ok, body = pcall(readfile, configStore.AutoloadFile)
	if not ok then
		return nil
	end
	local decodedOk, decoded = pcall(HttpService.JSONDecode, HttpService, body)
	return decodedOk and type(decoded) == "table" and decoded or nil
end

function configStore.WriteAutoload()
	local writefile = configStore.GetFunction("writefile")
	if not writefile or not configStore.EnsureFolders() then
		return false
	end
	local body = HttpService:JSONEncode({
		Enabled = configStore.AutoloadEnabled,
		Config = configStore.AutoloadName,
	})
	return pcall(writefile, configStore.AutoloadFile, body)
end

configStore.EnsureFolders()

