local function connect(signal, callback)
	local connection = signal:Connect(callback)
	table.insert(connections, connection)
	return connection
end

-- Roblox fires Idled only after its normal inactivity window. Send one harmless
-- controller click at that point instead of continuously injecting movement.
-- The connection is tracked with the rest of the hub and disconnects on unload.
	configStore.AntiAfkTriggerCount = 0
	configStore.AntiAfkLastActionSucceeded = true
configStore.AntiAfkConnection = connect(localPlayer.Idled, function()
	local ok = pcall(function()
		local virtualUser = game:GetService("VirtualUser")
		local cameraCFrame = workspace.CurrentCamera and workspace.CurrentCamera.CFrame or CFrame.new()
		virtualUser:CaptureController()
		virtualUser:Button2Down(Vector2.zero, cameraCFrame)
		task.wait(0.08)
		virtualUser:Button2Up(Vector2.zero, cameraCFrame)
	end)
	configStore.AntiAfkLastActionSucceeded = ok
	if ok then
		configStore.AntiAfkTriggerCount += 1
	end
end)

local function schedule(delaySeconds, callback)
	local thread
	thread = task.delay(delaySeconds, function()
		if unloaded then
			return
		end
		callback()
	end)
	table.insert(scheduledThreads, thread)
	return thread
end

local function create(className, properties, parent)
	local object = Instance.new(className)
	for property, value in pairs(properties or {}) do
		object[property] = value
	end
	object.Parent = parent
	return object
end

-- VirtualInputManager expects desktop coordinates, while GuiObject.AbsolutePosition
-- is reported in Roblox's inset-adjusted GUI coordinate space. Convert the center
-- point before dispatching synthetic mouse input so buttons line up with the cursor.
local function getVirtualInputPosition(guiObject)
	local topLeftInset = GuiService:GetGuiInset()
	return guiObject.AbsolutePosition + guiObject.AbsoluteSize * 0.5 + topLeftInset
end

