function configStore.ApplyTheme(themeName)
	local palette = configStore.ThemePalettes[themeName]
	if not palette then return false end
	local previous = table.clone(colors)
	local function swap(value)
		for key, oldColor in pairs(previous) do
			if typeof(oldColor) == "Color3" and value == oldColor and palette[key] then
				return palette[key]
			end
		end
		return value
	end
	for _, object in ipairs(screenGui:GetDescendants()) do
		if object:IsA("GuiObject") then
			object.BackgroundColor3 = swap(object.BackgroundColor3)
		end
		if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
			object.TextColor3 = swap(object.TextColor3)
			if object:IsA("TextBox") then object.PlaceholderColor3 = swap(object.PlaceholderColor3) end
		end
		if object:IsA("UIStroke") then object.Color = swap(object.Color) end
		if object:IsA("ScrollingFrame") then object.ScrollBarImageColor3 = swap(object.ScrollBarImageColor3) end
		if object:IsA("UIGradient") then
			object.Color = ColorSequence.new(palette.SurfaceRaised, palette.Background)
		end
	end
	for key, value in pairs(palette) do colors[key] = value end
	configStore.Theme = themeName
	for name, button in pairs(configStore.ThemeButtons) do
		button.BackgroundColor3 = name == themeName and colors.Accent or colors.Surface
		button.TextColor3 = name == themeName and colors.Background or colors.Muted
	end
	return true
end

