function configStore.ChatLog.UpdateCount()
	if configStore.ChatLog.CountLabel then
		configStore.ChatLog.CountLabel.Text = string.format("%d / %d", #configStore.ChatLog.Entries, configStore.ChatLog.MaxEntries)
	end
end

function configStore.ChatLog.Clear()
	for _, entry in ipairs(configStore.ChatLog.Entries) do
		if entry.Label then entry.Label:Destroy() end
	end
	table.clear(configStore.ChatLog.Entries)
	configStore.ChatLog.UpdateCount()
end

function configStore.ChatLog.Add(senderName, username, message, isSystem)
	if type(message) ~= "string" or message == "" or not configStore.ChatLog.List then return false end
	if not configStore.ChatLog.CaptureEnabled then return false end
	message = string.gsub(message, "[%z\1-\8\11\12\14-\31]", "")
	if #message > 300 then message = string.sub(message, 1, 297) .. "..." end
	local sender = tostring(senderName or "SYSTEM")
	local handle = type(username) == "string" and username ~= "" and username ~= sender and (" (@" .. username .. ")") or ""
	local timestamp = os.date("%H:%M:%S")
	local label = create("TextLabel", {
		Name = "Message",
		Size = UDim2.new(1, -2, 0, 20),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = isSystem and colors.AccentSoft or colors.SurfaceRaised,
		BackgroundTransparency = isSystem and 0.72 or 0.45,
		BorderSizePixel = 0,
		Font = Enum.Font.Code,
		Text = string.format("[%s] %s%s: %s", timestamp, sender, handle, message),
		TextColor3 = isSystem and colors.Accent or colors.Text,
		TextSize = 10,
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
	}, configStore.ChatLog.List)
	create("UICorner", {CornerRadius = UDim.new(0, 4)}, label)
	create("UIPadding", {
		PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5),
		PaddingLeft = UDim.new(0, 7), PaddingRight = UDim.new(0, 7),
	}, label)
	table.insert(configStore.ChatLog.Entries, {Label = label})
	while #configStore.ChatLog.Entries > configStore.ChatLog.MaxEntries do
		local oldest = table.remove(configStore.ChatLog.Entries, 1)
		if oldest and oldest.Label then oldest.Label:Destroy() end
	end
	configStore.ChatLog.UpdateCount()
	task.defer(function()
		if configStore.ChatLog.List and configStore.ChatLog.List.Parent then
			configStore.ChatLog.List.CanvasPosition = Vector2.new(0, math.max(0, configStore.ChatLog.List.AbsoluteCanvasSize.Y))
		end
	end)
	return true
end

