end

function configStore.ChatLog.ApplyNativeChatVisibility()
	local enabled = configStore.ChatLog.NativeChatVisible
	pcall(configStore.ChatLog.StarterGui.SetCoreGuiEnabled, configStore.ChatLog.StarterGui, Enum.CoreGuiType.Chat, enabled)
	pcall(function()
		configStore.TextChatService.ChatWindowConfiguration.Enabled = enabled
		configStore.TextChatService.ChatInputBarConfiguration.Enabled = enabled
	end)
end

function configStore.ChatLog.SetNativeChatVisible(enabled)
	if type(enabled) ~= "boolean" then return false end
	configStore.ChatLog.NativeChatVisible = enabled
	configStore.ChatLog.ApplyNativeChatVisibility()
	configStore.ChatLog.UpdateToggleVisuals()
	return true
end

function configStore.ChatLog.SetCaptureEnabled(enabled)
	if type(enabled) ~= "boolean" or configStore.ChatLog.CaptureEnabled == enabled then return false end
	if not enabled then configStore.ChatLog.Add("SYSTEM", nil, "Chat log capture paused.", true) end
	configStore.ChatLog.CaptureEnabled = enabled
	configStore.ChatLog.UpdateToggleVisuals()
	if enabled then configStore.ChatLog.Add("SYSTEM", nil, "Chat log capture resumed.", true) end
	return true
end

function configStore.ChatLog.RestoreNativeChat()
	if type(configStore.ChatLog.PreviousCoreChatVisible) == "boolean" then
		pcall(configStore.ChatLog.StarterGui.SetCoreGuiEnabled, configStore.ChatLog.StarterGui, Enum.CoreGuiType.Chat, configStore.ChatLog.PreviousCoreChatVisible)
	end
	pcall(function()
		if type(configStore.ChatLog.PreviousWindowVisible) == "boolean" then
			configStore.TextChatService.ChatWindowConfiguration.Enabled = configStore.ChatLog.PreviousWindowVisible
		end
		if type(configStore.ChatLog.PreviousInputVisible) == "boolean" then
			configStore.TextChatService.ChatInputBarConfiguration.Enabled = configStore.ChatLog.PreviousInputVisible
		end
	end)
end

connect(configStore.ChatLog.CaptureButton.Activated, function()
	configStore.ChatLog.SetCaptureEnabled(not configStore.ChatLog.CaptureEnabled)
end)
connect(configStore.ChatLog.NativeChatButton.Activated, function()
	configStore.ChatLog.SetNativeChatVisible(not configStore.ChatLog.NativeChatVisible)
end)
configStore.ChatLog.UpdateToggleVisuals()
configStore.ChatLog.ApplyNativeChatVisibility()
connect(RunService.Heartbeat, function(deltaTime)
	if not configStore.ChatLog.NativeChatVisible then return end
	configStore.ChatLog.NativeChatElapsed += deltaTime
	if configStore.ChatLog.NativeChatElapsed >= 1 then
		configStore.ChatLog.NativeChatElapsed = 0
		configStore.ChatLog.ApplyNativeChatVisibility()
	end
end)
if configStore.TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then
	connect(configStore.TextChatService.MessageReceived, function(chatMessage)
		local source = chatMessage.TextSource
		local player = source and Players:GetPlayerByUserId(source.UserId)
		if player then
			configStore.ChatLog.Add(player.DisplayName, player.Name, chatMessage.Text, false)
		else
			configStore.ChatLog.Add("SYSTEM", nil, chatMessage.Text, true)
		end
	end)
else
	function configStore.ChatLog.HookLegacyPlayer(player)
		connect(player.Chatted, function(message)
			configStore.ChatLog.Add(player.DisplayName, player.Name, message, false)
		end)
	end
	for _, player in ipairs(Players:GetPlayers()) do configStore.ChatLog.HookLegacyPlayer(player) end
	connect(Players.PlayerAdded, configStore.ChatLog.HookLegacyPlayer)
end
configStore.ChatLog.Add("SYSTEM", nil, "Chat logger active.", true)

