function configStore.ESP.GetDistanceAlpha(value)
	local minD = configStore.ESP.MinDistance or 500
	local maxD = configStore.ESP.MaxDistanceCap or 100000
	return math.clamp((value - minD) / (maxD - minD), 0, 1)
end

function configStore.ESP.SetMaxDistance(value)
	if type(value) ~= "number" then
		return false
	end
	local minD = configStore.ESP.MinDistance or 500
	local maxD = configStore.ESP.MaxDistanceCap or 100000
	configStore.ESP.MaxDistance = math.clamp(math.floor(value + 0.5), minD, maxD)
	local alpha = configStore.ESP.GetDistanceAlpha(configStore.ESP.MaxDistance)
	if configStore.ESP.DistanceFill then
		configStore.ESP.DistanceFill.Size = UDim2.fromScale(alpha, 1)
	end
	if configStore.ESP.DistanceKnob then
		configStore.ESP.DistanceKnob.Position = UDim2.fromScale(alpha, 0.5)
	end
	if configStore.ESP.DistanceValueLabel then
		configStore.ESP.DistanceValueLabel.Text = tostring(configStore.ESP.MaxDistance)
	end
	for _, entry in pairs(configStore.ESP.Entries) do
		if entry.Billboard then
			entry.Billboard.MaxDistance = configStore.ESP.MaxDistance
		end
		if entry.BoxBillboard then
			entry.BoxBillboard.MaxDistance = configStore.ESP.MaxDistance
		end
	end
	return true
end

function configStore.NpcESP.GetDistanceAlpha(value)
	return configStore.ESP.GetDistanceAlpha(value)
end

function configStore.NpcESP.SetMaxDistance(value)
	if type(value) ~= "number" then
		return false
	end
	local minD = configStore.NpcESP.MinDistance or 1000000
	local maxD = configStore.NpcESP.MaxDistanceCap or 1000000
	configStore.NpcESP.MaxDistance = math.clamp(math.floor(value + 0.5), minD, maxD)
	local alpha = configStore.NpcESP.GetDistanceAlpha(configStore.NpcESP.MaxDistance)
	if configStore.NpcESP.DistanceFill then
		configStore.NpcESP.DistanceFill.Size = UDim2.fromScale(alpha, 1)
	end
	if configStore.NpcESP.DistanceKnob then
		configStore.NpcESP.DistanceKnob.Position = UDim2.fromScale(alpha, 0.5)
	end
	if configStore.NpcESP.DistanceValueLabel then
		configStore.NpcESP.DistanceValueLabel.Text = tostring(configStore.NpcESP.MaxDistance)
	end
	for _, entry in pairs(configStore.NpcESP.Entries) do
		if entry.Billboard then
			entry.Billboard.MaxDistance = configStore.NpcESP.MaxDistance
		end
		if entry.BoxBillboard then
			entry.BoxBillboard.MaxDistance = configStore.NpcESP.MaxDistance
		end
	end
	return true
end

configStore.ESP.SetMaxDistance(configStore.ESP.MaxDistance)
configStore.NpcESP.SetMaxDistance(configStore.NpcESP.MaxDistance)

local function setPlayerEspMaxDistanceFromInputX(inputX)
	local track = configStore.ESP.DistanceTrack
	if not track or track.AbsoluteSize.X <= 0 then
		return
	end
	local alpha = math.clamp((inputX - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
	local minD = configStore.ESP.MinDistance or 500
	local maxD = configStore.ESP.MaxDistanceCap or 100000
	configStore.ESP.SetMaxDistance(minD + (maxD - minD) * alpha)
end

local function setNpcEspMaxDistanceFromInputX(inputX)
	local track = configStore.NpcESP.DistanceTrack
	if not track or track.AbsoluteSize.X <= 0 then
		return
	end
	local alpha = math.clamp((inputX - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
	local minD = configStore.NpcESP.MinDistance or 1000000
	local maxD = configStore.NpcESP.MaxDistanceCap or 1000000
	configStore.NpcESP.SetMaxDistance(minD + (maxD - minD) * alpha)
end

connect(configStore.ESP.DistanceHitbox.InputBegan, function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		configStore.ESP.DistanceSliderDragging = true
		setPlayerEspMaxDistanceFromInputX(input.Position.X)
	end
end)
connect(configStore.NpcESP.DistanceHitbox.InputBegan, function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		configStore.NpcESP.DistanceSliderDragging = true
		setNpcEspMaxDistanceFromInputX(input.Position.X)
	end
end)
connect(UserInputService.InputChanged, function(input)
