function configStore.ESP.GetSpectatePlayers()
	local candidates={}
	for _,player in ipairs(Players:GetPlayers()) do
		if player~=localPlayer then table.insert(candidates,player) end
	end
	table.sort(candidates,function(a,b) return string.lower(a.Name)<string.lower(b.Name) end)
	return candidates
end

function configStore.ESP.RenderSpectate()
	local selected=configStore.ESP.SpectateSelected
	if not selected or selected.Parent~=Players then
		selected=configStore.ESP.GetSpectatePlayers()[1]
		configStore.ESP.SpectateSelected=selected
	end
	configStore.ESP.SpectateLabel.Text=selected
		and ("SPECTATE // "..selected.DisplayName.."  @"..selected.Name)
		or "SPECTATE // NO OTHER PLAYERS"
	local active=configStore.ESP.SpectateTarget~=nil
	configStore.ESP.SpectateButton.Text=active and "STOP SPECTATING" or "SPECTATE"
	configStore.ESP.SpectateButton.BackgroundColor3=active and colors.Danger or colors.Accent
	configStore.ESP.SpectateButton.TextColor3=active and colors.Text or colors.Background
end

function configStore.ESP.StopSpectate()
	configStore.ESP.SpectateTarget=nil
	local camera=workspace.CurrentCamera
	local character=localPlayer.Character
	local humanoid=character and character:FindFirstChildOfClass("Humanoid")
	if camera and humanoid then
		camera.CameraType=Enum.CameraType.Custom
		camera.CameraSubject=humanoid
	end
	configStore.ESP.RenderSpectate()
	return true
end

function configStore.ESP.StartSpectate(player)
	player=player or configStore.ESP.SpectateSelected
	if not player or player==localPlayer or player.Parent~=Players then return false end
	local humanoid=player.Character and player.Character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return false end
	configStore.ESP.SpectateSelected=player
	configStore.ESP.SpectateTarget=player
	local camera=workspace.CurrentCamera
	if camera then
		camera.CameraType=Enum.CameraType.Custom
		camera.CameraSubject=humanoid
	end
	configStore.ESP.RenderSpectate()
	return true
end

function configStore.ESP.CycleSpectate(step)
	local candidates=configStore.ESP.GetSpectatePlayers()
	if #candidates==0 then
		configStore.ESP.SpectateSelected=nil
		configStore.ESP.StopSpectate()
		return nil
	end
	local index=table.find(candidates,configStore.ESP.SpectateSelected) or (step>0 and 0 or 1)
	index=((index-1+step)%#candidates)+1
	configStore.ESP.SpectateSelected=candidates[index]
	if configStore.ESP.SpectateTarget then configStore.ESP.StartSpectate(candidates[index]) else configStore.ESP.RenderSpectate() end
	return candidates[index]
end

function configStore.ESP.UpdateSpectate(deltaTime)
	configStore.ESP.SpectateElapsed+=deltaTime
	if configStore.ESP.SpectateElapsed<0.2 then return end
	configStore.ESP.SpectateElapsed=0
	local target=configStore.ESP.SpectateTarget
	if not target then return end
	if target.Parent~=Players then configStore.ESP.StopSpectate();return end
	local humanoid=target.Character and target.Character:FindFirstChildOfClass("Humanoid")
	local camera=workspace.CurrentCamera
	if humanoid and camera and camera.CameraSubject~=humanoid then camera.CameraSubject=humanoid end
end

function configStore.ESP.ReadNamedValue(root, names)
	if not root then return nil end
	for _, name in ipairs(names) do
		local object = root:FindFirstChild(name, true)
		if object and object:IsA("ValueBase") then return object.Value end
		local attribute = root:GetAttribute(name)
		if attribute ~= nil then return attribute end
	end
	return nil
end

function configStore.ESP.GetLocalSnapshot()
	local cached=configStore.ESP.LocalSnapshot or {}
	if (configStore.ESP.LocalSnapshot and os.clock()-configStore.ESP.LocalSnapshotAt<1) or configStore.ESP.LocalSnapshotInFlight then
		return cached
	end
	-- InvokeServer yields; fetch off the Heartbeat thread and serve the cached copy meanwhile.
	configStore.ESP.LocalSnapshotInFlight=true
	task.spawn(function()
		pcall(configStore.ESP.FetchLocalSnapshot)
		configStore.ESP.LocalSnapshotInFlight=false
	end)
	return cached
end

function configStore.ESP.FetchLocalSnapshot()
	local snapshot={}
	local okCharacter,characterData=pcall(statRetrieveRemote.InvokeServer,statRetrieveRemote,"CharacterData","TableStat")
	if okCharacter and type(characterData)=="table" then
		snapshot.Name=characterData.Name
		snapshot.Race=type(characterData.Race)=="table" and characterData.Race.Race or characterData.Race
	end
	local okStats,statData=pcall(statRetrieveRemote.InvokeServer,statRetrieveRemote,"StatData","TableStat")
	if okStats and type(statData)=="table" and type(statData.CharacterStats)=="table" then
		snapshot.Ki=statData.CharacterStats.Ki
		snapshot.MaxKi=statData.CharacterStats.MaxKi
	end
	configStore.ESP.LocalSnapshot=snapshot
	configStore.ESP.LocalSnapshotAt=os.clock()
	return snapshot
end

function configStore.ESP.GetRace(player)
	if player==localPlayer then
		local snapshot=configStore.ESP.GetLocalSnapshot()
		if snapshot.Race then return tostring(snapshot.Race) end
	end
	return tostring(configStore.ESP.ReadNamedValue(player:FindFirstChild("PlayerStats"), {"Race"})
		or configStore.ESP.ReadNamedValue(player.Character, {"Race"}) or player:GetAttribute("Race") or "Unknown")
end

function configStore.ESP.GetInGameName(player)
	if player==localPlayer then
		local snapshot=configStore.ESP.GetLocalSnapshot()
		if snapshot.Name then return tostring(snapshot.Name) end
	end
	local stats = player:FindFirstChild("PlayerStats")
	local characterData = stats and stats:FindFirstChild("CharacterData")
	return tostring(configStore.ESP.ReadNamedValue(characterData, {"Name","CharacterName","InGameName"})
		or configStore.ESP.ReadNamedValue(player.Character, {"CharacterName","InGameName"})
		or player:GetAttribute("CharacterName") or player.DisplayName)
end

function configStore.ESP.GetKi(player)
	if player==localPlayer then
		local snapshot=configStore.ESP.GetLocalSnapshot()
		if tonumber(snapshot.Ki) and tonumber(snapshot.MaxKi) then return tonumber(snapshot.Ki),tonumber(snapshot.MaxKi) end
	end
	local current = tonumber(configStore.ESP.ReadNamedValue(player.Character, {"Ki","CurrentKi"})
		or configStore.ESP.ReadNamedValue(player:FindFirstChild("PlayerStats"), {"Ki","CurrentKi"}))
	local maximum = tonumber(configStore.ESP.ReadNamedValue(player.Character, {"MaxKi","MaximumKi"})
		or configStore.ESP.ReadNamedValue(player:FindFirstChild("PlayerStats"), {"MaxKi","MaximumKi"}))
	return current, maximum
end

function configStore.ESP.GetPowerLevel(player)
	return tonumber(configStore.ESP.ReadNamedValue(player:FindFirstChild("PlayerStats"), {"PowerLevel"})
		or configStore.ESP.ReadNamedValue(player.Character, {"PowerLevel"})
		or player:GetAttribute("PowerLevel"))
end

function configStore.ESP.FormatInteger(value)
	local formatted=tostring(math.floor((tonumber(value) or 0)+0.5))
	repeat
		local replaced
		formatted,replaced=string.gsub(formatted,"^(-?%d+)(%d%d%d)","%1,%2")
	until replaced==0
	return formatted
end

function configStore.ESP.GetVisualMetrics(character, root)
	local camera=workspace.CurrentCamera
	local centerOffset=Vector3.zero
	if not camera then return 76,132,1,centerOffset,Vector3.new(0,4.2,0) end
	local rootPoint=camera:WorldToViewportPoint(root.Position)
	if rootPoint.Z<=0 then return 12,20,0.15,centerOffset,Vector3.new(0,4.2,0) end
	local halfWidth,halfHeight=0,0
	local highestPoint=2.8
	local bodyPartCount=0
	for _,part in ipairs(character:GetChildren()) do
		if part:IsA("BasePart") and part~=root and part.Transparency<0.98 then
			bodyPartCount+=1
			local half=part.Size*0.5
			for _,x in ipairs({-1,1}) do
				for _,y in ipairs({-1,1}) do
					for _,z in ipairs({-1,1}) do
						local worldPoint=part.CFrame:PointToWorldSpace(Vector3.new(half.X*x,half.Y*y,half.Z*z))
						local viewportPoint=camera:WorldToViewportPoint(worldPoint)
						if viewportPoint.Z>0 then
							halfWidth=math.max(halfWidth,math.abs(viewportPoint.X-rootPoint.X))
							halfHeight=math.max(halfHeight,math.abs(viewportPoint.Y-rootPoint.Y))
						end
						highestPoint=math.max(highestPoint,worldPoint.Y-root.Position.Y)
					end
				end
			end
		end
	end
	if bodyPartCount==0 then return 76,132,1,centerOffset,Vector3.new(0,4.2,0) end
	local boxWidth=math.clamp(halfWidth*2+4,28,76*1.5)
	local boxHeight=math.clamp(halfHeight*2+4,132*0.15,132*1.15)
	return boxWidth,boxHeight,1,centerOffset,Vector3.new(0,highestPoint+0.8,0)
end

function configStore.ESP.CreateEntry(player)
	if player == localPlayer and not configStore.ESP.Settings.Self then return nil end
	if configStore.ESP.Entries[player] then return configStore.ESP.Entries[player] end
	local entry = {}
	entry.Billboard = create("BillboardGui", {
		Name="GohanPlayerESP", Size=UDim2.fromOffset(240,88), StudsOffsetWorldSpace=Vector3.new(0,4.2,0),
		AlwaysOnTop=true, LightInfluence=0, MaxDistance=configStore.ESP.MaxDistance or 100000, Enabled=false,
	}, screenGui)
	entry.Panel = create("Frame", {AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0.5,0.5),Size=UDim2.fromOffset(240,88),BackgroundTransparency=1}, entry.Billboard)
	entry.InfoScale=create("UIScale",{Scale=1},entry.Panel)
	local function label(name, y, color, size)
		return create("TextLabel", {
			Name=name, Position=UDim2.fromOffset(0,y), Size=UDim2.new(1,0,0,15), BackgroundTransparency=1,
			Font=Enum.Font.GothamSemibold, Text="", TextColor3=color, TextSize=size or 11,
			TextStrokeColor3=Color3.new(0,0,0), TextStrokeTransparency=0.15,
		}, entry.Panel)
	end
	entry.Username = label("Username",0,Color3.fromRGB(255,255,255),12)
	entry.InGameName = label("InGameName",16,colors.Accent,11)
	entry.Race = label("Race",32,Color3.fromRGB(180,220,255),10)
	entry.PowerLevel = label("PowerLevel",48,Color3.fromRGB(255,214,72),10)
	entry.Distance = label("Distance",64,Color3.fromRGB(225,225,225),10)
	entry.DistanceStubBack = create("Frame", {
		Name = "DistanceStub",
		Position = UDim2.fromOffset(0, 78),
		Size = UDim2.new(1, 0, 0, 4),
		BackgroundColor3 = Color3.fromRGB(30, 30, 30),
		BackgroundTransparency = 0.15,
		BorderSizePixel = 0,
	}, entry.Panel)
	create("UICorner", {CornerRadius = UDim.new(0, 2)}, entry.DistanceStubBack)
	entry.DistanceStubFill = create("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		BackgroundColor3 = colors.Accent,
		BorderSizePixel = 0,
	}, entry.DistanceStubBack)
	create("UICorner", {CornerRadius = UDim.new(0, 2)}, entry.DistanceStubFill)
	entry.BoxBillboard=create("BillboardGui",{Name="GohanESPBox",Size=UDim2.fromOffset(76,132),StudsOffsetWorldSpace=Vector3.new(0,1.4,0),AlwaysOnTop=true,LightInfluence=0,MaxDistance=configStore.ESP.MaxDistance or 100000,Enabled=false},screenGui)
	entry.BoxFrame=create("Frame",{Size=UDim2.fromScale(1,1),BackgroundTransparency=1,BorderSizePixel=0},entry.BoxBillboard)
	entry.BoxStroke=create("UIStroke",{Color=Color3.new(1,1,1),Thickness=1.4,Transparency=0},entry.BoxFrame)
	local function bar(name,rightOffset,color)
		local back=create("Frame",{Name=name,AnchorPoint=Vector2.new(1,0),Position=UDim2.new(1,rightOffset,0,3),Size=UDim2.new(0,7,1,-6),BackgroundColor3=Color3.fromRGB(8,8,8),BackgroundTransparency=0.02,BorderSizePixel=0,ZIndex=3},entry.BoxFrame)
		create("UICorner",{CornerRadius=UDim.new(0,2)},back)
		create("UIStroke",{Color=Color3.fromRGB(15,15,15),Thickness=1,Transparency=0},back)
		local fill=create("Frame",{Name="Fill",AnchorPoint=Vector2.new(0,1),Position=UDim2.fromScale(0,1),Size=UDim2.fromScale(1,1),BackgroundColor3=color,BorderSizePixel=0,ZIndex=4},back)
		create("UICorner",{CornerRadius=UDim.new(0,2)},fill)
		return back,fill
	end
	entry.HealthBack,entry.HealthFill=bar("Health",-12,Color3.fromRGB(239,55,62))
	entry.KiBack,entry.KiFill=bar("Ki",-3,Color3.fromRGB(48,145,255))
	configStore.ESP.Entries[player]=entry
	return entry
end

function configStore.ESP.RemoveEntry(player)
	local entry=configStore.ESP.Entries[player]
	if not entry then return end
	if entry.Billboard then entry.Billboard:Destroy() end
	if entry.BoxBillboard then entry.BoxBillboard:Destroy() end
	configStore.ESP.Entries[player]=nil
end

function configStore.ESP.Clear()
	for player in pairs(configStore.ESP.Entries) do configStore.ESP.RemoveEntry(player) end
end

function configStore.ESP.RenderButtons()
	configStore.ESP.MasterButton.Text=configStore.ESP.Enabled and "PLAYER ESP: ON" or "PLAYER ESP: OFF"
	configStore.ESP.MasterButton.BackgroundColor3=configStore.ESP.Enabled and colors.Accent or colors.Surface
	configStore.ESP.MasterButton.TextColor3=configStore.ESP.Enabled and colors.Background or colors.Muted
	for key,button in pairs(configStore.ESP.Buttons) do
		local enabled=configStore.ESP.Settings[key]==true
		button.BackgroundColor3=enabled and colors.SurfaceRaised or colors.Surface
		local state=button:FindFirstChild("State")
		if state then state.Text=enabled and "ON" or "OFF";state.TextColor3=enabled and colors.Success or colors.Muted end
	end
end

function configStore.ESP.SetEnabled(enabled)
	configStore.ESP.Enabled=enabled==true
	if not configStore.ESP.Enabled then configStore.ESP.Clear() end
	configStore.ESP.RenderButtons()
	return configStore.ESP.Enabled
end

function configStore.ESP.SetSetting(key, enabled)
	if configStore.ESP.Settings[key]==nil then return false end
	configStore.ESP.Settings[key]=enabled==true
	if key=="Self" and not configStore.ESP.Settings.Self then configStore.ESP.RemoveEntry(localPlayer) end
	configStore.ESP.RenderButtons()
	return true
end

function configStore.ESP.Update(deltaTime)
	configStore.ESP.UpdateSpectate(deltaTime)
	if not configStore.ESP.Enabled then return end
	configStore.ESP.UpdateElapsed+=deltaTime
	if configStore.ESP.UpdateElapsed<0.1 then return end
	configStore.ESP.UpdateElapsed=0
	local localRoot=localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
	for _,player in ipairs(Players:GetPlayers()) do
		if player~=localPlayer or configStore.ESP.Settings.Self then
			local entry=configStore.ESP.CreateEntry(player)
			if not entry then continue end
			local character=player.Character
			local humanoid=character and character:FindFirstChildOfClass("Humanoid")
			local root=character and character:FindFirstChild("HumanoidRootPart")
			local head=character and character:FindFirstChild("Head")
			local active=humanoid~=nil and humanoid.Health>0 and root~=nil and head~=nil
			local distance=(localRoot and root) and (root.Position-localRoot.Position).Magnitude or math.huge
			local maxDistance=configStore.ESP.MaxDistance or 100000
			local inRange=distance<=maxDistance
			local showInfo=configStore.ESP.Settings.Username or configStore.ESP.Settings.InGameName or configStore.ESP.Settings.Race or configStore.ESP.Settings.PowerLevel or configStore.ESP.Settings.Distance
			entry.Billboard.Enabled=active==true and inRange and showInfo
			entry.BoxBillboard.Enabled=active==true and inRange and (configStore.ESP.Settings.Box or configStore.ESP.Settings.HealthBar or configStore.ESP.Settings.KiBar)
			entry.BoxStroke.Enabled=configStore.ESP.Settings.Box
			entry.Billboard.Adornee=root
			entry.BoxBillboard.Adornee=root
			if active then
				local boxWidth,boxHeight,_,centerOffset,infoOffset=configStore.ESP.GetVisualMetrics(character,root)
				entry.Billboard.Size=UDim2.fromOffset(240,88)
				entry.Panel.Size=UDim2.fromOffset(240,88)
				entry.Billboard.StudsOffsetWorldSpace=infoOffset
				entry.InfoScale.Scale=1
				entry.BoxBillboard.Size=UDim2.fromOffset(boxWidth,boxHeight)
				entry.BoxBillboard.StudsOffsetWorldSpace=centerOffset
				entry.Username.Visible=configStore.ESP.Settings.Username
				entry.Username.Text="@"..player.Name
				entry.InGameName.Visible=configStore.ESP.Settings.InGameName
				entry.Race.Visible=configStore.ESP.Settings.Race
				entry.PowerLevel.Visible=configStore.ESP.Settings.PowerLevel
				-- Stat lookups use recursive FindFirstChild; refresh them once a second, not every update.
				local now=os.clock()
				if not entry.StatsRefreshedAt or now-entry.StatsRefreshedAt>=1 then
					entry.StatsRefreshedAt=now
					entry.InGameName.Text=configStore.ESP.GetInGameName(player)
					entry.Race.Text="RACE // "..configStore.ESP.GetRace(player)
					local powerLevel=configStore.ESP.GetPowerLevel(player)
					entry.PowerLevel.Text=powerLevel and "POWER // "..configStore.ESP.FormatInteger(powerLevel) or "POWER // --"
					entry.CachedKi,entry.CachedMaxKi=configStore.ESP.GetKi(player)
				end
				entry.Distance.Visible=configStore.ESP.Settings.Distance
				entry.Distance.Text=localRoot and string.format("%.0f STUDS",distance) or "-- STUDS"
				if entry.DistanceStubBack then
					entry.DistanceStubBack.Visible = configStore.ESP.Settings.Distance
					entry.DistanceStubFill.Size = UDim2.fromScale(math.clamp(distance / maxDistance, 0, 1), 1)
				end
				local hpMax=math.max(humanoid.MaxHealth,1)
				entry.HealthBack.Visible=configStore.ESP.Settings.HealthBar
				entry.HealthFill.Size=UDim2.fromScale(1,math.clamp(humanoid.Health/hpMax,0,1))
				local ki,maxKi=entry.CachedKi,entry.CachedMaxKi
				entry.KiBack.Visible=configStore.ESP.Settings.KiBar
				entry.KiFill.Size=UDim2.fromScale(1,ki and maxKi and maxKi>0 and math.clamp(ki/maxKi,0,1) or 0)
			end
		end
	end
	for player in pairs(configStore.ESP.Entries) do if not player.Parent then configStore.ESP.RemoveEntry(player) end end
end

connect(configStore.ESP.MasterButton.Activated,function() configStore.ESP.SetEnabled(not configStore.ESP.Enabled) end)
for key,button in pairs(configStore.ESP.Buttons) do
	connect(button.Activated,function() configStore.ESP.SetSetting(key,not configStore.ESP.Settings[key]) end)
end
connect(configStore.ESP.SpectatePrevious.Activated,function() configStore.ESP.CycleSpectate(-1) end)
connect(configStore.ESP.SpectateNext.Activated,function() configStore.ESP.CycleSpectate(1) end)
connect(configStore.ESP.SpectateButton.Activated,function()
	if configStore.ESP.SpectateTarget then configStore.ESP.StopSpectate() else configStore.ESP.StartSpectate() end
end)
connect(Players.PlayerAdded,function() configStore.ESP.RenderSpectate() end)
connect(Players.PlayerRemoving,function(player)
	configStore.ESP.RemoveEntry(player)
	if configStore.ESP.SpectateTarget==player then configStore.ESP.StopSpectate() end
	if configStore.ESP.SpectateSelected==player then
		configStore.ESP.SpectateSelected=nil
		task.defer(configStore.ESP.RenderSpectate)
	end
end)
connect(RunService.Heartbeat,configStore.ESP.Update)
configStore.ESP.RenderButtons()
configStore.ESP.RenderSpectate()

