function qolState.SetCameraClipEnabled(enabled)
	if type(enabled) ~= "boolean" then
		return false
	end
	if not enabled and not qolState.CameraClipEnabled then
		qolState.CameraClipButton.Text = "Camera Clip: OFF"
		qolState.CameraClipButton.BackgroundColor3 = colors.Surface
		qolState.CameraClipButton.TextColor3 = colors.Muted
		return true
	end
	if enabled and not qolState.CameraClipEnabled then
		local ok, currentMode = pcall(function()
			return localPlayer.DevCameraOcclusionMode
		end)
		qolState.PreviousOcclusionMode = ok and currentMode or Enum.DevCameraOcclusionMode.Zoom
	end
	local ok = pcall(function()
		localPlayer.DevCameraOcclusionMode = enabled
			and Enum.DevCameraOcclusionMode.Invisicam
			or (qolState.PreviousOcclusionMode or Enum.DevCameraOcclusionMode.Zoom)
	end)
	if not ok then
		return false
	end
	qolState.CameraClipEnabled = enabled
	qolState.CameraClipButton.Text = enabled and "Camera Clip: ON" or "Camera Clip: OFF"
	qolState.CameraClipButton.BackgroundColor3 = enabled and colors.Accent or colors.Surface
	qolState.CameraClipButton.TextColor3 = enabled and colors.Text or colors.Muted
	if not enabled then
		qolState.PreviousOcclusionMode = nil
	end
	return true
end

connect(qolState.CameraClipButton.Activated, function()
	qolState.SetCameraClipEnabled(not qolState.CameraClipEnabled)
end)

