function qolState.SetNoclipEnabled(enabled)
	if type(enabled) ~= "boolean" then
		return false
	end

	qolState.NoclipEnabled = enabled
	qolState.NoclipButton.Text = enabled and "Noclip: ON" or "Noclip: OFF"
	qolState.NoclipButton.BackgroundColor3 = enabled and colors.Accent or colors.Surface
	qolState.NoclipButton.TextColor3 = enabled and colors.Text or colors.Muted

	local character = localPlayer.Character
	if enabled then
		if character then
			for _, descendant in ipairs(character:GetDescendants()) do
				if descendant:IsA("BasePart") then
					if npcCollisionStates[descendant] == nil then
						npcCollisionStates[descendant] = descendant.CanCollide
					end
					descendant.CanCollide = false
				end
			end
		end
	else
		for part, previousCanCollide in pairs(npcCollisionStates) do
			if part and part.Parent then
				pcall(function()
					part.CanCollide = previousCanCollide
				end)
			end
		end
		npcCollisionStates = {}
	end
	return true
end

connect(qolState.NoclipButton.Activated, function()
	qolState.SetNoclipEnabled(not qolState.NoclipEnabled)
end)

function qolState.ResetCharacter()
	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	if not character or not humanoid or humanoid.Health <= 0 or qolState.ResetCharacterPending == character then
		return false
	end
	qolState.ResetCharacterPending = character
	task.spawn(function()
		local nextCharacter = localPlayer.CharacterAdded:Wait()
		if nextCharacter ~= character and qolState.ResetCharacterPending == character then
			qolState.ResetCharacterPending = nil
		end
	end)
	task.delay(8, function()
		if qolState.ResetCharacterPending == character then
			qolState.ResetCharacterPending = nil
		end
	end)
	local resetEvent = remotes:FindFirstChild("ResetEvent")
	if resetEvent and resetEvent:IsA("RemoteEvent") then
		local ok = pcall(resetEvent.FireServer, resetEvent, character)
		if ok then return true end
	end
	pcall(humanoid.ChangeState, humanoid, Enum.HumanoidStateType.Dead)
	pcall(character.BreakJoints, character)
	humanoid.Health = 0
	return true
end

connect(qolState.ResetButton.Activated, qolState.ResetCharacter)

