function configStore.AutoClash.MakeButton(name, text, position, size)
	local button = create("TextButton", {
		Name = name,
		AnchorPoint = Vector2.new(1, 0),
		Position = position,
		Size = size,
		AutoButtonColor = false,
		BackgroundColor3 = colors.Surface,
		BorderSizePixel = 0,
		Font = Enum.Font.GothamSemibold,
		Text = text,
		TextColor3 = colors.Muted,
		TextSize = 10,
	}, configStore.AutoClash.Card)
	create("UICorner", {CornerRadius = UDim.new(0, 6)}, button)
	create("UIStroke", {Color = colors.AccentSoft, Thickness = 1}, button)
	return button
end
