configStore.WebhookFile = configStore.Root .. "/webhook.json"
if type(environment.__GohanHubWebhookSettings) ~= "table" then
	environment.__GohanHubWebhookSettings = {URL = "", Enabled = false, PowerStep = 10000}
	pcall(function()
		local isfile = configStore.GetFunction("isfile")
		local readfile = configStore.GetFunction("readfile")
		if isfile and readfile and isfile(configStore.WebhookFile) then
			local saved = HttpService:JSONDecode(readfile(configStore.WebhookFile))
			if type(saved) == "table" then
				environment.__GohanHubWebhookSettings.URL = type(saved.URL) == "string" and saved.URL or ""
				environment.__GohanHubWebhookSettings.Enabled = saved.Enabled == true
				environment.__GohanHubWebhookSettings.PowerStep = tonumber(saved.PowerStep) or 10000
			end
		end
	end)
end
