function configStore.Webhook.SetStatus(message, color)
	if configStore.Webhook.StatusLabel then
		configStore.Webhook.StatusLabel.Text = tostring(message)
		configStore.Webhook.StatusLabel.TextColor3 = color or colors.Muted
	end
end

function configStore.Webhook.IsValidUrl(url)
	if type(url) ~= "string" then return false end
	for _, prefix in ipairs({
		"https://discord.com/api/webhooks/",
		"https://canary.discord.com/api/webhooks/",
		"https://ptb.discord.com/api/webhooks/",
		"https://discordapp.com/api/webhooks/",
	}) do
		if string.sub(url, 1, #prefix) == prefix and #url > #prefix + 8 then return true end
	end
	return false
end

function configStore.Webhook.MaskUrl()
	configStore.Webhook.UrlBox.Text = configStore.Webhook.URL ~= "" and "https://discord.com/api/webhooks/********" or ""
end

function configStore.Webhook.SyncSettings()
	environment.__GohanHubWebhookSettings.URL = configStore.Webhook.URL
	environment.__GohanHubWebhookSettings.Enabled = configStore.Webhook.Enabled
	environment.__GohanHubWebhookSettings.PowerStep = configStore.Webhook.PowerStep
	pcall(function()
		local writefile = configStore.GetFunction("writefile")
		if writefile then
			configStore.EnsureFolders()
			writefile(configStore.WebhookFile, HttpService:JSONEncode({
				URL = configStore.Webhook.URL,
				Enabled = configStore.Webhook.Enabled,
				PowerStep = configStore.Webhook.PowerStep,
			}))
		end
	end)
	configStore.Webhook.ToggleButton.Text = configStore.Webhook.Enabled and "ALERTS: ON" or "ALERTS: OFF"
	configStore.Webhook.ToggleButton.BackgroundColor3 = configStore.Webhook.Enabled and colors.Accent or colors.Surface
	configStore.Webhook.ToggleButton.TextColor3 = configStore.Webhook.Enabled and colors.Background or colors.Muted
end

function configStore.Webhook.SetUrl(url)
	url = type(url) == "string" and string.gsub(url, "%s+", "") or ""
	if not configStore.Webhook.IsValidUrl(url) then
		configStore.Webhook.MaskUrl()
		configStore.Webhook.SetStatus("Invalid URL. Only Discord /api/webhooks/ URLs are accepted.", colors.DangerHover)
		return false
	end
	configStore.Webhook.URL = url
	configStore.Webhook.SyncSettings()
	configStore.Webhook.MaskUrl()
	configStore.Webhook.SetStatus("Webhook saved. Click TEST to verify it, then turn ALERTS on.", colors.Success)
	return true
end

function configStore.Webhook.GetRequestFunction()
	if type(environment.request) == "function" then return environment.request end
	if type(environment.http_request) == "function" then return environment.http_request end
	if type(environment.syn) == "table" and type(environment.syn.request) == "function" then return environment.syn.request end
	return nil
end

configStore.Webhook.Queue = {}

function configStore.Webhook.Send(title, description, color, force)
	local url = configStore.Webhook.URL
	if not configStore.Webhook.IsValidUrl(url) then
		if force then
			configStore.Webhook.SetStatus("Paste your Discord webhook URL above first.", colors.DangerHover)
		end
		return false
	end
	if not force and not configStore.Webhook.Enabled then
		return false
	end
	local requestFunction = configStore.Webhook.GetRequestFunction()
	if not requestFunction then
		configStore.Webhook.SetStatus("This executor does not expose an HTTP request function.", colors.DangerHover)
		return false
	end
	if configStore.Webhook.Busy then
		if #configStore.Webhook.Queue < 25 then
			table.insert(configStore.Webhook.Queue, {title, description, color, force})
			return true
		end
		return false
	end
	configStore.Webhook.Busy = true
	task.spawn(function()
		local payload = {
			username = HUB_DISPLAY_NAME .. " Alerts",
			allowed_mentions = {parse = {}},
			embeds = {{
				title = tostring(title or (HUB_DISPLAY_NAME .. " Alert")),
				description = string.sub(tostring(description or ""), 1, 1500),
				color = tonumber(color) or 2731390,
				fields = {
					{name = "Player", value = localPlayer.DisplayName .. " (@" .. localPlayer.Name .. ")", inline = true},
					{name = "Location", value = tostring(currentPlanet), inline = true},
					{name = "Game", value = "https://www.roblox.com/games/" .. tostring(game.PlaceId), inline = false},
				},
				timestamp = DateTime.now():ToIsoDate(),
			}},
		}
		local encodedOk, body = pcall(HttpService.JSONEncode, HttpService, payload)
		local sentOk, response = false, nil
		if encodedOk then
			sentOk, response = pcall(requestFunction, {
				Url = url,
				Method = "POST",
				Headers = {["Content-Type"] = "application/json"},
				Body = body,
			})
		end
		local statusCode = type(response) == "table" and tonumber(response.StatusCode or response.Status) or nil
		local accepted = sentOk and (statusCode == nil or (statusCode >= 200 and statusCode < 300))
		configStore.Webhook.Busy = false
		configStore.Webhook.LastSentAt = accepted and os.clock() or configStore.Webhook.LastSentAt
		configStore.Webhook.SetStatus(accepted and (tostring(title) .. " alert sent.") or ("Webhook failed" .. (statusCode and (" (HTTP " .. statusCode .. ")") or ".")), accepted and colors.Success or colors.DangerHover)
		local nextAlert = table.remove(configStore.Webhook.Queue, 1)
		if nextAlert and not unloaded then
			-- Space queued posts out to stay under Discord's webhook rate limit.
			task.wait(1.2)
			configStore.Webhook.Send(nextAlert[1], nextAlert[2], nextAlert[3], nextAlert[4])
		end
	end)
	return true
end

function configStore.Webhook.SetEnabled(enabled)
	if type(enabled) ~= "boolean" then return false end
	if enabled and not configStore.Webhook.IsValidUrl(configStore.Webhook.URL) then
		configStore.Webhook.SetStatus("Enter a valid Discord webhook URL before enabling alerts.", colors.DangerHover)
		return false
	end
	configStore.Webhook.Enabled = enabled
	configStore.Webhook.SyncSettings()
	configStore.Webhook.SetStatus(enabled and "Webhook alerts enabled." or "Webhook alerts paused.", enabled and colors.Success or colors.Muted)
	return true
end

function configStore.Webhook.MonitorLevelValue(value, mode)
	if not value or not value:IsA("ValueBase") then return false end
	if configStore.Webhook.LevelValue == value and configStore.Webhook.LevelMode == mode then
		return true
	end
	if configStore.Webhook.LevelConnection then
		configStore.Webhook.LevelConnection:Disconnect()
		configStore.Webhook.LevelConnection = nil
	end
	configStore.Webhook.LevelValue = value
	configStore.Webhook.LevelMode = mode
	configStore.Webhook.LevelConnection = connect(value:GetPropertyChangedSignal("Value"), function()
		configStore.Webhook.OnLevelObserved(value.Value, "stat value " .. value:GetFullName())
	end)
	configStore.Webhook.OnLevelObserved(value.Value, "stat value " .. value:GetFullName())
	return true
end

function configStore.Webhook.OnLevelObserved(level, source)
	level = tonumber(level)
	if not level then
		return
	end
	level = math.floor(level)
	local previous = configStore.Webhook.LastLevelValue
	configStore.Webhook.LastLevelValue = level
	configStore.Webhook.LevelSource = source or configStore.Webhook.LevelSource
	if configStore.Session then
		configStore.Session.OnLevel(level)
	end
	if not previous then
		configStore.Webhook.SetStatus(string.format("Level %d detected; level-up alerts active.", level), colors.Success)
		print(string.format("[%s] Level %d detected from %s", HUB_DISPLAY_NAME, level, tostring(source)))
		return
	end
	if level <= previous then
		return
	end
	for reached = previous + 1, math.min(level, previous + 25) do
		configStore.Webhook.Send(
			"Level Up",
			string.format("Reached level %d on %s.", reached, tostring(currentPlanet)),
			5763719
		)
	end
end

configStore.Webhook.LevelKeys = {"Level", "Lvl", "CharacterLevel", "PlayerLevel"}

function configStore.Webhook.PickLevelField(data)
	if type(data) ~= "table" then
		return nil
	end
	for _, key in ipairs(configStore.Webhook.LevelKeys) do
		local value = data[key]
		if type(value) == "table" then
			value = value.Value or value.Current
		end
		if tonumber(value) then
			return tonumber(value), key
		end
	end
	return nil
end

function configStore.Webhook.ReadLevelFromServer()
	for _, key in ipairs(configStore.Webhook.LevelKeys) do
		local ok, value = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, key)
		if ok and tonumber(value) then
			return tonumber(value), "StatRetrieveRemote(\"" .. key .. "\")"
		end
	end
	local okStats, statData = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "StatData", "TableStat")
	local okCharacter, characterData = pcall(statRetrieveRemote.InvokeServer, statRetrieveRemote, "CharacterData", "TableStat")
	statData = okStats and type(statData) == "table" and statData or nil
	characterData = okCharacter and type(characterData) == "table" and characterData or nil
	local candidates = {
		{"StatData", statData},
		{"StatData.CharacterStats", statData and statData.CharacterStats},
		{"StatData.CoreStats", statData and statData.CoreStats},
		{"StatData.Progression", statData and statData.Progression},
		{"CharacterData", characterData},
		{"CharacterData.Stats", characterData and characterData.Stats},
	}
	for _, candidate in ipairs(candidates) do
		local level, key = configStore.Webhook.PickLevelField(candidate[2])
		if level then
			return level, candidate[1] .. "." .. key
		end
	end
	return nil, nil, statData, characterData
end

function configStore.Webhook.ReadLevelFromAttributes()
	local playerStats = localPlayer:FindFirstChild("PlayerStats")
	for _, instance in ipairs({localPlayer, localPlayer.Character, playerStats}) do
		if instance then
			for _, key in ipairs(configStore.Webhook.LevelKeys) do
				local value = tonumber(instance:GetAttribute(key))
				if value then
					return value, instance.Name .. " attribute " .. key
				end
			end
		end
	end
	return nil
end

function configStore.Webhook.DescribeKeys(data)
	if type(data) ~= "table" then
		return "(unavailable)"
	end
	local keys = {}
	for key, value in pairs(data) do
		table.insert(keys, tostring(key) .. (type(value) == "table" and "{}" or ""))
	end
	table.sort(keys)
	return table.concat(keys, ", ")
end

function configStore.Webhook.PollLevel()
	if configStore.Webhook.LevelPollInFlight or unloaded then
		return
	end
	if configStore.Webhook.LevelValue and configStore.Webhook.LevelValue.Parent then
		return
	end
	local value = configStore.Webhook.FindLevelValue()
	if value then
		configStore.Webhook.MonitorLevelValue(value, "Level")
		return
	end
	local attributeLevel, attributeSource = configStore.Webhook.ReadLevelFromAttributes()
	if attributeLevel then
		configStore.Webhook.OnLevelObserved(attributeLevel, attributeSource)
		return
	end
	configStore.Webhook.LevelPollInFlight = true
	local ok, level, source, statData, characterData = pcall(configStore.Webhook.ReadLevelFromServer)
	configStore.Webhook.LevelPollInFlight = false
	if ok and level then
		configStore.Webhook.OnLevelObserved(level, source)
	elseif not configStore.Webhook.LevelDiagnosticPrinted then
		configStore.Webhook.LevelDiagnosticPrinted = true
		configStore.Webhook.SetStatus("Level stat not found; see console (F9) for the stat keys.", colors.DangerHover)
		warn(string.format("[%s] Level stat not found. StatData: %s", HUB_DISPLAY_NAME, configStore.Webhook.DescribeKeys(statData)))
		warn(string.format("[%s] StatData.CharacterStats: %s", HUB_DISPLAY_NAME,
			configStore.Webhook.DescribeKeys(type(statData) == "table" and statData.CharacterStats)))
		warn(string.format("[%s] StatData.CoreStats: %s", HUB_DISPLAY_NAME,
			configStore.Webhook.DescribeKeys(type(statData) == "table" and statData.CoreStats)))
		warn(string.format("[%s] CharacterData: %s", HUB_DISPLAY_NAME, configStore.Webhook.DescribeKeys(characterData)))
	end
end

function configStore.Webhook.FindLevelValue()
	local playerStats = localPlayer:FindFirstChild("PlayerStats")
	local leaderstats = localPlayer:FindFirstChild("leaderstats")
	if leaderstats then
		local direct = leaderstats:FindFirstChild("Level") or leaderstats:FindFirstChild("Lvl")
		if direct and direct:IsA("ValueBase") then
			return direct
		end
	end
	local statData = playerStats and playerStats:FindFirstChild("StatData")
	local coreStats = statData and statData:FindFirstChild("CoreStats")
	if coreStats then
		local coreLevel = coreStats:FindFirstChild("Level") or coreStats:FindFirstChild("Lvl")
		if coreLevel and coreLevel:IsA("ValueBase") then
			return coreLevel
		end
	end
	for _, root in ipairs({leaderstats, playerStats, statData, coreStats}) do
		if root then
			for _, descendant in ipairs(root:GetDescendants()) do
				if (descendant.Name == "Level" or descendant.Name == "Lvl") and descendant:IsA("ValueBase") then
					return descendant
				end
			end
		end
	end
	return nil
end

function configStore.Webhook.TryMonitorLevel()
	task.spawn(configStore.Webhook.PollLevel)
end

