function configStore.NpcESP.RemoveEntry(model)
	local entry = configStore.NpcESP.Entries[model]
	if not entry then
		return
	end
	if entry.Billboard then
		entry.Billboard:Destroy()
	end
	if entry.BoxBillboard then
		entry.BoxBillboard:Destroy()
	end
	configStore.NpcESP.Entries[model] = nil
end

function configStore.NpcESP.Clear()
	for model in pairs(configStore.NpcESP.Entries) do
		configStore.NpcESP.RemoveEntry(model)
	end
end

function configStore.NpcESP.RenderButtons()
	local master = configStore.NpcESP.MasterButton
	if master then
		master.Text = configStore.NpcESP.Enabled and "NPC ESP: ON" or "NPC ESP: OFF"
		master.BackgroundColor3 = configStore.NpcESP.Enabled and colors.Accent or colors.Surface
		master.TextColor3 = configStore.NpcESP.Enabled and colors.Background or colors.Muted
	end
	for key, button in pairs(configStore.NpcESP.Buttons) do
		local enabled = configStore.NpcESP.Settings[key] == true
		button.BackgroundColor3 = enabled and colors.SurfaceRaised or colors.Surface
		local state = button:FindFirstChild("State")
		if state then
			state.Text = enabled and "ON" or "OFF"
			state.TextColor3 = enabled and colors.Success or colors.Muted
		end
	end
end

function configStore.NpcESP.SetEnabled(enabled)
	configStore.NpcESP.Enabled = enabled == true
	if not configStore.NpcESP.Enabled then
		configStore.NpcESP.Clear()
	end
	configStore.NpcESP.RenderButtons()
	return configStore.NpcESP.Enabled
end

function configStore.NpcESP.SetSetting(key, enabled)
	if configStore.NpcESP.Settings[key] == nil then
		return false
	end
	configStore.NpcESP.Settings[key] = enabled == true
	configStore.NpcESP.RenderButtons()
	return true
end

function configStore.NpcESP.Update(deltaTime)
	if not configStore.NpcESP.Enabled then
		return
	end
	configStore.NpcESP.UpdateElapsed += deltaTime
	if configStore.NpcESP.UpdateElapsed < 0.12 then
		return
	end
	configStore.NpcESP.UpdateElapsed = 0
	local localRoot = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
	local activeModels = {}
	for _, npc in ipairs(configStore.NpcESP.EnumerateModels()) do
		local model, root, humanoid = npc.Model, npc.Root, npc.Humanoid
		activeModels[model] = true
		local entry = configStore.NpcESP.CreateEntry(model)
		local distance = localRoot and (root.Position - localRoot.Position).Magnitude or math.huge
		local maxDistance = configStore.NpcESP.MaxDistance or 1000000
		local inRange = distance <= maxDistance
		local showInfo = configStore.NpcESP.Settings.Name
			or configStore.NpcESP.Settings.PowerLevel
			or configStore.NpcESP.Settings.Distance
		entry.Billboard.Enabled = inRange and showInfo
		entry.BoxBillboard.Enabled = inRange
			and (configStore.NpcESP.Settings.Box or configStore.NpcESP.Settings.HealthBar)
		entry.BoxStroke.Enabled = configStore.NpcESP.Settings.Box
		entry.Billboard.Adornee = root
		entry.BoxBillboard.Adornee = root
		if inRange then
			local boxWidth, boxHeight, _, centerOffset, infoOffset = configStore.ESP.GetVisualMetrics(model, root)
			entry.Billboard.StudsOffsetWorldSpace = infoOffset
			entry.BoxBillboard.Size = UDim2.fromOffset(boxWidth, boxHeight)
			entry.BoxBillboard.StudsOffsetWorldSpace = centerOffset
			entry.NameLabel.Visible = configStore.NpcESP.Settings.Name
			entry.NameLabel.Text = model.Name
			local powerLevel = npcSafety.GetNpcPowerLevel(model)
			entry.PowerLevel.Visible = configStore.NpcESP.Settings.PowerLevel
			entry.PowerLevel.Text = powerLevel and ("POWER // " .. configStore.ESP.FormatInteger(powerLevel)) or "POWER // --"
			entry.Distance.Visible = configStore.NpcESP.Settings.Distance
			entry.Distance.Text = localRoot and string.format("%.0f STUDS", distance) or "-- STUDS"
			if entry.DistanceStubBack then
				entry.DistanceStubBack.Visible = configStore.NpcESP.Settings.Distance
				entry.DistanceStubFill.Size = UDim2.fromScale(math.clamp(distance / maxDistance, 0, 1), 1)
			end
			local hpMax = math.max(humanoid.MaxHealth, 1)
			entry.HealthBack.Visible = configStore.NpcESP.Settings.HealthBar
			entry.HealthFill.Size = UDim2.fromScale(1, math.clamp(humanoid.Health / hpMax, 0, 1))
		end
	end
	for model in pairs(configStore.NpcESP.Entries) do
		if not model.Parent or not activeModels[model] then
			configStore.NpcESP.RemoveEntry(model)
		end
	end
end

connect(configStore.NpcESP.MasterButton.Activated, function()
	configStore.NpcESP.SetEnabled(not configStore.NpcESP.Enabled)
end)
for key, button in pairs(configStore.NpcESP.Buttons) do
	connect(button.Activated, function()
		configStore.NpcESP.SetSetting(key, not configStore.NpcESP.Settings[key])
	end)
end
