local function bindTrainingButton(object)
	if not configStore.TrainingEnabled then return end
	if boundTrainingButtons[object] or not object:IsA("GuiButton") or not trainingButtonNames[object.Name] then
		return
	end

	local meditateGui = playerGui:FindFirstChild("MeditateGui")
	if not meditateGui or not object:IsDescendantOf(meditateGui) then
		return
	end

	local function onSelected()
		if trainingDefinitionByButton[object.Name] then
			startTrainingSession(object.Name)
		elseif activeTrainingButton then
			stopTrainingSession("Ready - selected training is not automated")
		end
	end
	boundTrainingButtons[object] = {
		connect(object.MouseButton1Down, onSelected),
		connect(object.Activated, onSelected),
	}
end

for _, descendant in ipairs(playerGui:GetDescendants()) do
	bindTrainingButton(descendant)
end

