local function setAutoStartEnabled(enabled)
	local autoBuildState = qolState.StatAllocate
	if enabled == false and autoBuildState.PersistentAutoEnabled and not autoBuildState.InternalTrainingToggle then
		autoBuildState.PersistentAutoEnabled = false
		autoBuildState.WaitingForGtp = false
		autoBuildState.AutoBuildElapsed = 0
		autoBuildState.RenderAuto()
		if activeTrainingButton then stopTrainingSession("Auto Build stopped manually.") end
	end
	if not configStore.TrainingEnabled then
		autoStartEnabled = false
		local prompt = configStore.ShowPremiumUpgrade
		if enabled and type(prompt) == "function" then prompt("Auto Training") end
		return false
	end
	autoStartEnabled = enabled
	if enabled then
		autoStartFailedLaunches = 0
	end
	autoStartButton.Text = autoStartEnabled and "Auto Training: ON" or "Auto Training: OFF"
	autoStartButton.TextColor3 = autoStartEnabled and colors.Text or colors.Muted
	autoStartButton.BackgroundColor3 = autoStartEnabled and colors.Accent or colors.Surface
	autoStartLastAttemptAt = 0
	if autoStartEnabled then
		setTrainingStatus("Auto Start enabled - preparing selected stat...", colors.Success)
	else
		setTrainingStatus("Auto Start disabled", colors.Muted)
	end
	return autoStartEnabled
end
