local function updateTrainingTargetPresence(found, finishGap)
	local now = os.clock()
	if found then
		autoStartFailedLaunches = 0
		trainingSessionSawTargets = true
		trainingLastTargetsAt = now
		return true
	end

	if trainingSessionSawTargets and now - trainingLastTargetsAt > (finishGap or 1.5) then
		local definition = trainingDefinitionByButton[activeTrainingButton]
		stopTrainingSession((definition and definition.Label or "Training") .. " finished - ready again")
	elseif not trainingSessionSawTargets
		and now - trainingSessionStartedAt > (activeTrainingButton == "Control" and 12 or 5) then
		if autoStartEnabled and autoStartFailedLaunches >= 3 then
			setAutoStartEnabled(false)
			stopTrainingSession("Auto Start paused after 3 failed launches")
		else
			stopTrainingSession("Minigame did not start - ready again")
		end
	end
	return false
end

