-- Returns the slider's centre and the goal's edges in bar pixels. It is built
-- from Position/Size rather than AbsolutePosition, which only updates on the
-- next render and still shows the old goal for a frame after it moves.
function configStore.DurabilityTrainer.Measure(bar, goal, slider)
	local barWidth = bar.AbsoluteSize.X > 0 and bar.AbsoluteSize.X or 1
	local function span(object)
		local width = barWidth * object.Size.X.Scale + object.Size.X.Offset
		local left = barWidth * object.Position.X.Scale + object.Position.X.Offset - object.AnchorPoint.X * width
		return left, width
	end
	local goalLeft, goalWidth = span(goal)
	local sliderLeft, sliderWidth = span(slider)
	return sliderLeft + sliderWidth / 2, goalLeft, goalLeft + goalWidth
end

configStore.AutoClash.DigitKeys = {
	["0"] = "Zero", ["1"] = "One", ["2"] = "Two", ["3"] = "Three", ["4"] = "Four",
	["5"] = "Five", ["6"] = "Six", ["7"] = "Seven", ["8"] = "Eight", ["9"] = "Nine",
}

function configStore.AutoClash.ParseKey(text)
	if type(text) ~= "string" then
		return nil
	end
	local cleaned = string.upper((string.gsub(text, "<[^>]->", "")))
	cleaned = (string.gsub(cleaned, "[%s%[%]%(%)]", ""))
	if cleaned == "SPACE" or cleaned == "SPACEBAR" then
		return Enum.KeyCode.Space
	end
	if cleaned == "LMB" or cleaned == "M1" or cleaned == "CLICK" or cleaned == "MOUSE1" then
		return "Click"
	end
	if #cleaned ~= 1 then
		return nil
	end
	if string.match(cleaned, "%a") then
		return Enum.KeyCode[cleaned]
	end
	local digit = configStore.AutoClash.DigitKeys[cleaned]
	return digit and Enum.KeyCode[digit] or nil
end

function configStore.AutoClash.IsHubGui(object)
	return object == screenGui or screenGui:IsAncestorOf(object)
		or string.find(string.lower(object:GetFullName()), "anomalyhub", 1, true) ~= nil
end

function configStore.AutoClash.IsScoped(object)
	if configStore.AutoClash.IsHubGui(object) then
		return false
	end
	if object.Name == "LetterLabel" and object.Parent and object.Parent.Name == "PopupGui" then
		return true
	end
	local ancestor = object
	while ancestor and ancestor ~= playerGui do
		local lowerName = string.lower(ancestor.Name)
		for _, word in ipairs(configStore.AutoClash.ScopeWords) do
			if string.find(lowerName, word, 1, true) then
				return true
			end
		end
		ancestor = ancestor.Parent
	end
	return false
end

-- "named" candidates sit in a clash-named GUI and may show any key. "broad"
-- candidates are any other text on screen or on the character, and only count
-- when they show a lone W/A/S/D, which is what the game's clash box displays.
function configStore.AutoClash.Consider(object)
	if not (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox"))
		or configStore.AutoClash.IsHubGui(object) or object:FindFirstAncestor("MobilePad") then
		return
	end
	configStore.AutoClash.Candidates[object] = configStore.AutoClash.IsScoped(object) and "named" or "broad"
end

configStore.AutoClash.MovementKeys = {
	[Enum.KeyCode.W] = true, [Enum.KeyCode.A] = true, [Enum.KeyCode.S] = true, [Enum.KeyCode.D] = true,
}

configStore.AutoClash.WorldGuis = {}

function configStore.AutoClash.Rescan()
	table.clear(configStore.AutoClash.Candidates)
	table.clear(configStore.AutoClash.PromptState)
	table.clear(configStore.AutoClash.WorldGuis)
	for _, descendant in ipairs(playerGui:GetDescendants()) do
		configStore.AutoClash.Consider(descendant)
	end
	for _, descendant in ipairs(workspace:GetDescendants()) do
		if descendant:IsA("LayerCollector") then
			configStore.AutoClash.WorldGuis[descendant] = true
		elseif descendant:IsA("TextLabel") or descendant:IsA("TextButton") or descendant:IsA("TextBox") then
			if descendant:FindFirstAncestorWhichIsA("LayerCollector") then
				configStore.AutoClash.Consider(descendant)
			end
		end
	end
end

-- Screen GUIs must sit in the middle of the screen so HUD keybind hints near the
-- edges are never pressed; world billboards must be close to the local player.
function configStore.AutoClash.IsNearScreenCenter(object)
	local layer = object:FindFirstAncestorWhichIsA("LayerCollector")
	if layer and not layer:IsA("ScreenGui") then
		local anchor = layer:IsA("BillboardGui") and layer.Adornee or nil
		anchor = anchor or layer.Parent
		if anchor and anchor:IsA("Attachment") then
			anchor = anchor.Parent
		end
		local root = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
		if root and anchor and (anchor:IsA("BasePart") or anchor:IsA("Model")) then
			local position = anchor:IsA("BasePart") and anchor.Position or anchor:GetPivot().Position
			return (position - root.Position).Magnitude <= 60
		end
		return true
	end
	local camera = workspace.CurrentCamera
	if not camera then
		return false
	end
	local viewport = camera.ViewportSize
	local center = object.AbsolutePosition + object.AbsoluteSize / 2
	return math.abs(center.X - viewport.X / 2) <= viewport.X * 0.25
		and math.abs(center.Y - viewport.Y / 2) <= viewport.Y * 0.3
end

function configStore.AutoClash.IsAcceptedColor(color)
	return color.G > 0.5 and color.G > color.R + 0.2 and color.G > color.B + 0.15
end

-- The game tints the prompt green once the right key lands, then shows the
-- next letter. Seeing green clear again is how a repeated letter is detected.
function configStore.AutoClash.LooksAccepted(object)
	if configStore.AutoClash.IsAcceptedColor(object.TextColor3) then
		return true
	end
	local parent = object.Parent
	if parent and parent:IsA("GuiObject") and parent.BackgroundTransparency < 0.9
		and configStore.AutoClash.IsAcceptedColor(parent.BackgroundColor3) then
		return true
	end
	for _, holder in ipairs({object, parent}) do
		local stroke = holder and holder:FindFirstChildOfClass("UIStroke")
		if stroke and stroke.Enabled and stroke.Transparency < 0.9 and configStore.AutoClash.IsAcceptedColor(stroke.Color) then
			return true
		end
	end
	return false
end

function configStore.AutoClash.Press(key, object)
	configStore.AutoClash.Presses += 1
	if key == "Click" then
		if object:IsA("GuiButton") then
			task.spawn(sendMouseClick, object)
			return
		end
		local camera = workspace.CurrentCamera
		local center = camera and camera.ViewportSize / 2 or Vector2.new(400, 300)
		pcall(function()
			VirtualInputManager:SendMouseButtonEvent(center.X, center.Y, 0, true, game, 0)
		end)
		task.delay(0.035, function()
			pcall(function()
				VirtualInputManager:SendMouseButtonEvent(center.X, center.Y, 0, false, game, 0)
			end)
		end)
		return
	end
	pcall(function()
		VirtualInputManager:SendKeyEvent(true, key, false, game)
	end)
	task.delay(0.045 + math.random() * 0.05, function()
		pcall(function()
			VirtualInputManager:SendKeyEvent(false, key, false, game)
		end)
	end)
end

-- Reaction delay modelled on a recorded manual clash (0.40-0.57s per letter),
-- tuned slightly quicker with natural spread and the odd slow press.
function configStore.AutoClash.HumanDelay()
	local clash = configStore.AutoClash
	local spread = (math.random() + math.random() + math.random() - 1.5) / 1.5
	local delay = clash.ReactionMean + spread * clash.ReactionSpread
	if math.random() < 0.08 then
		delay += 0.08 + math.random() * 0.1
	end
	return math.clamp(delay, clash.ReactionMin, clash.ReactionMax)
end

function configStore.AutoClash.SetStatus(text, color)
	local label = configStore.AutoClash.StatusLabel
	if label.Text ~= text then
		label.Text = text
	end
	label.TextColor3 = color or colors.Muted
end

function configStore.AutoClash.Update()
	local clash = configStore.AutoClash
	if not clash.Enabled or unloaded then
		return
	end
	-- The ring requires angular timing; generic clash retries must not press it.
	local contest = playerGui:FindFirstChild("MindContest")
	local contestRoot = contest and contest:FindFirstChild("Root")
	if contestRoot and contestRoot:IsA("GuiObject") and isGuiVisible(contestRoot) then
		if contestRoot:FindFirstChild("Board", true) then
			if not configStore.AutoMaze.Enabled then
				clash.SetStatus("MAZE // ENABLE AUTO MAZE TO SOLVE THIS BOARD", colors.Muted)
			end
		elseif not configStore.BodyRing.Enabled then
			clash.SetStatus("BODY RING // ENABLE AUTO BODY RING TO TIME SPACE", colors.Muted)
		end
		return
	end
	if activeTrainingButton then
		clash.SetStatus("CLASH // PAUSED WHILE AUTO TRAINING RUNS", colors.Muted)
		return
	end
	local now = os.clock()
	local activePrompt = nil
	local clashGui = playerGui:FindFirstChild("ClashGui")
	local hud = clashGui and clashGui:FindFirstChild("ClashHUD")
	local keyPrompt = hud and hud:FindFirstChild("KeyPrompt")
	local letter = keyPrompt and keyPrompt:FindFirstChild("Letter")
	if letter and letter:IsA("TextLabel") then
		clash.Candidates[letter] = "named"
	end
	for object, scope in pairs(clash.Candidates) do
		if not object.Parent then
			clash.Candidates[object] = nil
			clash.PromptState[object] = nil
			continue
		end
		local state = clash.PromptState[object]
		local key = clash.ParseKey(object.Text)
		if key and scope == "broad" and not clash.MovementKeys[key] then
			key = nil
		end
		if key and not isGuiVisible(object) then
			key = nil
		end
		if key and scope == "broad" and not clash.IsNearScreenCenter(object) then
			key = nil
		end
		if key then
			local accepted = clash.LooksAccepted(object)
			local fresh = not state or not state.Visible or state.Text ~= object.Text
				or (state.WasAccepted and not accepted)
			if fresh then
				state = {
					Text = object.Text,
					ShownAt = now,
					PressAt = now + (clash.Mash and 0 or clash.HumanDelay()),
				}
				clash.PromptState[object] = state
			end
			state.Visible = true
			state.WasAccepted = accepted
			if accepted then
				state.PressAt = nil
			elseif state.PressAt and now >= state.PressAt then
				state.PressAt = nil
				state.PressedAt = now
				clash.LastReaction = now - state.ShownAt
				clash.Press(key, object)
			elseif not state.PressAt and state.PressedAt then
				-- Still white after a press: try again, quicker than the first reaction.
				local retryAfter = clash.Mash and clash.MashInterval or clash.RetryInterval
				if now - state.PressedAt >= retryAfter then
					state.PressAt = now + (clash.Mash and 0 or 0.08 + math.random() * 0.12)
				end
			end
			activePrompt = object
		elseif state then
			state.Visible = false
		end
	end
	if activePrompt then
		clash.LastPromptAt = now
		clash.SetStatus(string.format("CLASH // PRESSING %s // %d PRESSES // LAST REACTION %s",
			string.upper(activePrompt.Text), clash.Presses,
			clash.LastReaction and string.format("%.2fs", clash.LastReaction) or "--"), colors.Success)
	elseif not clash.LastPromptAt or now - clash.LastPromptAt > 2 then
		clash.SetStatus(string.format("CLASH // WAITING FOR A W/A/S/D PROMPT // %d PRESSES", clash.Presses), colors.Accent)
	end
end

-- Ring coordinates come directly from the recorded MindContest GUI. The arc
-- wraps around zero, so use its largest empty gap to find the occupied interval.
function configStore.BodyRing.AngleDelta(angle, origin)
	return (angle - origin + 180) % 360 - 180
end

function configStore.BodyRing.ArcWindow(angles)
	if #angles < 2 then return nil end
	table.sort(angles)
	local largest, start = -1, 0
	for index, angle in ipairs(angles) do
		local nextAngle = angles[index + 1] or angles[1] + 360
		if nextAngle - angle > largest then
			largest, start = nextAngle - angle, nextAngle % 360
		end
	end
	local width = 360 - largest
	if width < 4 or width >= 180 then return nil end
	return (start + width / 2) % 360, width
end

function configStore.BodyRing.Release()
	local body = configStore.BodyRing
	if body.KeyHeld then
		pcall(VirtualInputManager.SendKeyEvent, VirtualInputManager, false, Enum.KeyCode.Space, false, game)
		body.KeyHeld = false
	end
end

function configStore.BodyRing.SetEnabled(enabled)
	local body = configStore.BodyRing
	body.Release()
	body.Enabled = enabled == true
	body.State = nil
	body.Button.Text = body.Enabled and "Auto Body Ring: ON" or "Auto Body Ring: OFF"
	body.Button.BackgroundColor3 = body.Enabled and colors.Accent or colors.Surface
	body.Button.TextColor3 = body.Enabled and colors.Background or colors.Muted
end

function configStore.BodyRing.Update()
	local body = configStore.BodyRing
	if not body.Enabled or unloaded then return end
	local now = os.clock()
	if body.KeyHeld and now >= body.ReleaseAt then body.Release() end
	local contest = playerGui:FindFirstChild("MindContest")
	local root = contest and contest:FindFirstChild("Root")
	local card = root and root:FindFirstChild("Card")
	local ring = card and card:FindFirstChild("Ring")
	if card and card:FindFirstChild("Board") then
		body.State = nil
		body.Release()
		return
	end
	local spin = ring and ring:FindFirstChild("Spin")
	local arc = ring and ring:FindFirstChild("Arc")
	local note = card and card:FindFirstChild("Note")
	if not card or not card:IsA("GuiObject") or not isGuiVisible(card) then
		body.State = nil
		body.Release()
		return
	end
	local status = note and note:IsA("TextLabel") and string.upper(note.Text) or ""
	if not spin or not spin:IsA("GuiObject") or not isGuiVisible(spin) or not arc
		or string.find(status, "GET READY", 1, true) or string.find(status, "WON", 1, true)
		or string.find(status, "LOST", 1, true) then
		body.State = nil
		body.Release()
		configStore.AutoClash.SetStatus("BODY RING // " .. (status ~= "" and status or "WAITING FOR NEEDLE"), colors.Muted)
		return
	end
	if activeTrainingButton or UserInputService:GetFocusedTextBox() then
		body.State = nil
		body.Release()
		configStore.AutoClash.SetStatus("BODY RING // PAUSED FOR TRAINING OR TEXT INPUT", colors.Muted)
		return
	end
	local angles = {}
	for _, segment in ipairs(arc:GetChildren()) do
		if segment:IsA("GuiObject") and segment.Visible then
			table.insert(angles, segment.Rotation % 360)
		end
	end
	local center, width = body.ArcWindow(angles)
	if not center then
		configStore.AutoClash.SetStatus("BODY RING // WAITING FOR TARGET ARC", colors.Muted)
		return
	end
	local state = body.State
	if not state or state.Spin ~= spin or math.abs(body.AngleDelta(center, state.Center)) > 0.5
		or math.abs(width - state.Width) > 0.5 then
		state = {Spin = spin, Center = center, Width = width}
		body.State = state
	end
	local angle = spin.Rotation % 360
	local elapsed = state.SampleAt and now - state.SampleAt or 0
	local speed = elapsed > 0 and elapsed <= 0.12 and body.AngleDelta(angle, state.Angle) / elapsed or nil
	state.Angle, state.SampleAt = angle, now
	-- Press on the first sampled arc boundary, with no inward padding.
	-- No reaction timer: both the observed and projected angles must be inside,
	-- so prediction cannot fire early or queue an input after the window closes.
	local halfWindow = width / 2
	local predicted = angle + (speed or 0) * math.min(elapsed * 0.5, 0.016)
	local inside = math.abs(body.AngleDelta(angle, center)) <= halfWindow
		and math.abs(body.AngleDelta(predicted, center)) <= halfWindow
	if not state.Pressed and not body.KeyHeld and speed
		and math.abs(speed) >= 1 and math.abs(speed) <= 1440 and inside then
		local ok = pcall(VirtualInputManager.SendKeyEvent, VirtualInputManager, true, Enum.KeyCode.Space, false, game)
		if ok then
			state.Pressed = true
			body.Presses += 1
			body.KeyHeld = true
			body.ReleaseAt = now + 0.045
		else
			body.SetEnabled(false)
			configStore.AutoClash.SetStatus("BODY RING // KEYBOARD INPUT UNAVAILABLE", colors.DangerHover)
			return
		end
	end
	configStore.AutoClash.SetStatus(string.format("BODY RING // %s // %d PRESSES",
		state.Pressed and "WAITING FOR NEXT ROUND" or "TIMING ARC ENTRY", body.Presses), colors.Success)
end

connect(configStore.BodyRing.Button.Activated, function()
	configStore.BodyRing.SetEnabled(not configStore.BodyRing.Enabled)
end)
connect(RunService.RenderStepped, configStore.BodyRing.Update)

-- Read the circuit's current UI, then search private copies of the game's
-- CircuitRouter state. Actual moves always go through ordinary WASD input.
function configStore.AutoMaze.Clone(value, seen)
	if type(value) ~= "table" then return value end
	seen = seen or {}
	if seen[value] then return seen[value] end
	local copy = {}
	seen[value] = copy
	for key, item in pairs(value) do copy[key] = configStore.AutoMaze.Clone(item, seen) end
	return copy
end

function configStore.AutoMaze.StateKey(state)
	local parts = {tostring(state.X), tostring(state.Y)}
	for _, cell in ipairs(state.Trail or {}) do
		table.insert(parts, tostring(cell[1]) .. "," .. tostring(cell[2]))
	end
	return table.concat(parts, ";")
end

function configStore.AutoMaze.Search(router, initial, alive)
	local maze = configStore.AutoMaze
	local queue = {{State = initial, Parent = 0}}
	local seen = {[maze.StateKey(initial)] = true}
	local read, started = 1, os.clock()
	while read <= #queue do
		if not alive() then return nil, "canceled" end
		if read > 4000 or #queue > 12000 or os.clock() - started > 3 then return nil, "search limit reached" end
		local node = queue[read]
		for _, key in ipairs({"U", "R", "D", "L"}) do
			local trial = maze.Clone(node.State)
			local ok, result = pcall(router.Step, trial, key)
			if not ok or type(result) ~= "table" then return nil, "maze rules unavailable" end
			if result.Event ~= "Burn" and result.Event ~= "Buzz" and result.Event ~= "Reset"
				and (trial.X ~= node.State.X or trial.Y ~= node.State.Y) then
				local stamp = maze.StateKey(trial)
				if not seen[stamp] then
					seen[stamp] = true
					local child = {State = trial, Parent = read, Key = key,
						Cells = type(result.Path) == "table" and #result.Path or 1}
					table.insert(queue, child)
					if result.Event == "Goal" then
						local route, cursor = {}, #queue
						while queue[cursor].Parent ~= 0 do
							local move = queue[cursor]
							table.insert(route, 1, {Key = move.Key, X = move.State.X, Y = move.State.Y, Cells = move.Cells})
							cursor = move.Parent
						end
						return route
					end
				end
			end
		end
		read += 1
		if read % 32 == 0 then task.wait() end
	end
	return nil, "no safe route from this position"
end

function configStore.AutoMaze.Cell(model, object)
	local x = (object.Position.X.Offset - model.Offset) / model.Step + 1
	local y = (object.Position.Y.Offset - model.Offset) / model.Step + 1
	local ix, iy = math.round(x), math.round(y)
	if math.abs(x - ix) > 0.025 or math.abs(y - iy) > 0.025
		or ix < 1 or iy < 1 or ix > model.W or iy > model.H then return nil end
	return ix, iy
end

function configStore.AutoMaze.ReadBoard(grid)
	local maze = configStore.AutoMaze
	local head, core = grid:FindFirstChild("Head"), grid:FindFirstChild("Core")
	if not head or not core or not head:IsA("GuiObject") or not core:IsA("GuiObject") then return nil end
	local pixels, cell = grid.Size.X.Offset, head.Size.X.Offset
	if pixels <= 0 or cell <= 0 or grid.Size.Y.Offset ~= pixels then return nil end
	-- Match the renderer's cell/gap formula, independent of screen UIScale.
	for _, gap in ipairs({2, 1}) do
		local n = math.floor((pixels + gap) / (cell + gap))
		if n >= 2 and n <= 40 and (n >= 14 and gap == 1 or n < 14 and gap == 2)
			and math.floor((pixels + gap) / n) - gap == cell then
			local model = {W = n, H = n, Step = cell + gap, Cell = cell,
				Offset = math.floor((pixels - (n * (cell + gap) - gap)) / 2), Head = head, Grid = grid}
			local sx, sy = maze.Cell(model, head)
			local gx, gy = maze.Cell(model, core)
			if not sx or not gx then continue end
			local rows, valid = {}, true
			for y = 1, n do rows[y] = table.create(n, "0") end
			for _, wall in ipairs(grid:GetChildren()) do
				if wall.Name == "W" and wall:IsA("GuiObject") then
					local x, y = maze.Cell(model, wall)
					if not x then valid = false; break end
					rows[y][x] = "1"
				end
			end
			if not valid or rows[sy][sx] == "1" or rows[gy][gx] == "1" then continue end
			for y = 1, n do rows[y] = table.concat(rows[y]) end
			model.Layout = {W = n, H = n, Rows = rows, Start = {sx, sy}, Goal = {gx, gy}}
			model.Signature = table.concat(rows, "/") .. ":" .. gx .. "," .. gy
			return model
		end
	end
	return nil
end

function configStore.AutoMaze.Release()
	local maze = configStore.AutoMaze
	if maze.HeldKey then
		pcall(VirtualInputManager.SendKeyEvent, VirtualInputManager, false, maze.HeldKey, false, game)
		maze.HeldKey = nil
	end
end

function configStore.AutoMaze.SetEnabled(enabled)
	local maze = configStore.AutoMaze
	maze.Release()
	maze.Generation += 1
	maze.Session = nil
	maze.Enabled = enabled == true
	maze.Button.Text = maze.Enabled and "Auto Maze: ON" or "Auto Maze: OFF"
	maze.Button.BackgroundColor3 = maze.Enabled and colors.Accent or colors.Surface
	maze.Button.TextColor3 = maze.Enabled and colors.Background or colors.Muted
end

function configStore.AutoMaze.Press(key)
	local maze = configStore.AutoMaze
	if maze.HeldKey then return false end
	local code = Enum.KeyCode[key]
	if not code then return false end
	local ok = pcall(VirtualInputManager.SendKeyEvent, VirtualInputManager, true, code, false, game)
	if ok then
		maze.HeldKey, maze.ReleaseAt = code, os.clock() + 0.035
		maze.Presses += 1
	end
	return ok
end

function configStore.AutoMaze.Plan(session, model)
	local maze = configStore.AutoMaze
	session.Planning = true
	local generation = maze.Generation
	task.spawn(function()
		local function alive()
			return not unloaded and maze.Enabled and maze.Generation == generation and maze.Session == session
				and model.Head.Parent == model.Grid and model.Grid:IsDescendantOf(playerGui)
		end
		local ok, route, reason = pcall(function()
			local modules = ReplicatedStorage:FindFirstChild("Modules")
			local sharedModules = modules and modules:FindFirstChild("Shared")
			local module = sharedModules and sharedModules:FindFirstChild("CircuitRouter")
			if not module then return nil, "CircuitRouter not found" end
			local router = require(module)
			if not alive() then return nil, "canceled" end
			if type(router) ~= "table" or type(router.NewState) ~= "function" or type(router.Step) ~= "function" then
				return nil, "maze rules unavailable"
			end
			local initial = router.NewState(model.Layout)
			if type(initial) ~= "table" or type(initial.Trail) ~= "table" then return nil, "unsupported maze state" end
			return maze.Search(router, initial, alive)
		end)
		if not alive() then return end
		session.Planning = false
		if not ok then
			session.Error = "could not read maze rules"
			warn("[Anomaly's Hub] Auto Maze: " .. tostring(route))
		elseif not route then
			session.Error = reason
		else
			session.Route, session.Index = route, 1
		end
	end)
end

function configStore.AutoMaze.Update()
	local maze = configStore.AutoMaze
	if not maze.Enabled or unloaded then return end
	local now = os.clock()
	if maze.HeldKey and now >= maze.ReleaseAt then maze.Release() end
	local contest = playerGui:FindFirstChild("MindContest")
	local root = contest and contest:FindFirstChild("Root")
	local card = root and root:FindFirstChild("Card")
	local board = card and card:FindFirstChild("Board")
	local grid = board and board:FindFirstChild("Grid")
	if not grid or not grid:IsA("GuiObject") or not isGuiVisible(grid) then
		maze.Release()
		maze.Session = nil
		return
	end
	local function status(text) configStore.AutoClash.SetStatus("MAZE // " .. text, colors.Accent) end
	local note, lock = card:FindFirstChild("Note"), card:FindFirstChild("Lock")
	local text = note and note:IsA("TextLabel") and string.upper(note.Text) or ""
	if text ~= "GO" then maze.Release(); status(text ~= "" and text or "WAITING FOR START"); return end
	if activeTrainingButton or UserInputService:GetFocusedTextBox() then
		maze.Release(); status("PAUSED FOR TRAINING OR TEXT INPUT"); return
	end
	if lock and lock:IsA("TextLabel") and lock.Text ~= "" then maze.Release(); status(lock.Text); return end
	local head = grid:FindFirstChild("Head")
	if not head then return end
	local session = maze.Session
	if not session or session.Grid ~= grid or session.Head ~= head then
		maze.Generation += 1
		maze.Release()
		session = {Grid = grid, Head = head, ResetCount = 0}
		maze.Session = session
	end
	if session.Planning then status("CALCULATING ROUTE"); return end
	if session.Error then status(session.Error); return end
	local model = maze.ReadBoard(grid)
	if not model then status("WAITING FOR MOVEMENT TO SETTLE"); return end
	if session.Signature and session.Signature ~= model.Signature then
		maze.Generation += 1
		maze.Release()
		session.Route, session.Pending, session.ResetCount = nil, nil, 0
	end
	session.Signature = model.Signature
	local x, y = model.Layout.Start[1], model.Layout.Start[2]
	if x == model.Layout.Goal[1] and y == model.Layout.Goal[2] then maze.Release(); status("CORE REACHED"); return end
	local trail = grid:FindFirstChild("Trail")
	local hasTrail = trail and #trail:GetChildren() > 0
	if session.ResetAt then
		if not hasTrail and now - session.ResetAt >= 0.12 then
			session.ResetAt = nil
		elseif now - session.ResetAt > 1.5 then
			session.Error = "RESET NOT CONFIRMED; TOGGLE AUTO MAZE TO RETRY"
			return
		else status("RESETTING PARTIAL TRAIL"); return end
	end
	if not session.Route then
		if hasTrail then
			if session.ResetCount >= 2 then session.Error = "POSITION CHANGED REPEATEDLY; TOGGLE AUTO MAZE TO RETRY"; return end
			if maze.Press("R") then session.ResetCount += 1; session.ResetAt = now end
			status("RESETTING PARTIAL TRAIL")
		else
			session.StartX, session.StartY = x, y
			maze.Plan(session, model)
			status("CALCULATING ROUTE")
		end
		return
	end
	local pending = session.Pending
	if pending then
		if now < pending.Until then return end
		if x == pending.X and y == pending.Y then
			session.Index += 1
			session.Pending = nil
			session.Unconfirmed = 0
		elseif now - pending.SentAt > 0.8 then
			session.Unconfirmed = (session.Unconfirmed or 0) + 1
			if session.Unconfirmed >= 3 then
				session.Error = "MOVES NOT REGISTERING; TOGGLE AUTO MAZE TO RETRY"
				maze.Release()
				return
			end
			session.Route, session.Pending = nil, nil
			status("POSITION CHANGED; REPLANNING")
			return
		else status("WAITING FOR MOVE CONFIRMATION"); return end
	end
	if maze.HeldKey then return end
	local previous = session.Route[session.Index - 1]
	local expectedX, expectedY = previous and previous.X or session.StartX, previous and previous.Y or session.StartY
	if x ~= expectedX or y ~= expectedY then session.Route = nil; status("POSITION CHANGED; REPLANNING"); return end
	local move = session.Route[session.Index]
	if not move then status("WAITING FOR RESULT"); return end
	local keys = {U = "W", D = "S", L = "A", R = "D"}
	if maze.Press(keys[move.Key]) then
		session.Pending = {X = move.X, Y = move.Y, SentAt = now,
			Until = now + math.clamp(move.Cells * 0.025, 0.04, 0.22) + 0.025}
		status(string.format("%s // MOVE %d/%d", keys[move.Key], session.Index, #session.Route))
	else
		session.Error = "KEYBOARD INPUT UNAVAILABLE"
	end
end

