function configStore.UpdateHomeDashboard()
	currentPlanet = getCurrentPlanet()
	configStore.HomeValueLabels.Planet.Text = currentPlanet
	configStore.SignalLabel.Text = (isBetaEnvironment and "[" .. HUB_VERSION .. " BETA] LINK ACTIVE\n" or "[" .. HUB_VERSION .. "] LINK ACTIVE\n")
		.. string.upper(currentPlanet)
	configStore.HomeValueLabels.Ping.Text = configStore.GetPingText()
	configStore.HomeValueLabels.Region.Text = configStore.StripInfoPrefix(configStore.GetServerInfoLabelText("ServerRegion"))
	configStore.HomeValueLabels.Server.Text = configStore.GetServerInfoLabelText("ServerName")
	configStore.HomeValueLabels.Uptime.Text = configStore.StripInfoPrefix(configStore.GetServerInfoLabelText("Uptime"))
	local antiAfkActive = configStore.AntiAfkConnection ~= nil and configStore.AntiAfkConnection.Connected
		and configStore.AntiAfkLastActionSucceeded
	configStore.HomeValueLabels.AntiAFK.Text = antiAfkActive
		and (configStore.AntiAfkTriggerCount > 0 and string.format("ACTIVE · %d DEFENSE%s",
			configStore.AntiAfkTriggerCount, configStore.AntiAfkTriggerCount == 1 and "" or "S") or "ACTIVE")
		or "INACTIVE"
	configStore.HomeValueLabels.AntiAFK.TextColor3 = antiAfkActive and colors.Success or colors.DangerHover

	local licenseState = type(environment.GohanHubLicense) == "table" and environment.GohanHubLicense or nil
	if licenseState and licenseState.status == "authenticated" then
		local tier = string.upper(tostring(licenseState.tier or "premium"))
		local hint = type(licenseState.keyHint) == "string" and licenseState.keyHint or "HIDDEN"
		local expiryText = "LIFETIME"
		if type(licenseState.expiresAt) == "number" then
			local remaining = math.max(0, math.floor((licenseState.expiresAt / 1000) - os.time()))
			if remaining <= 0 then
				expiryText = "EXPIRED"
			elseif remaining >= 86400 then
				expiryText = string.format("%dD %dH LEFT", math.floor(remaining / 86400), math.floor((remaining % 86400) / 3600))
			elseif remaining >= 3600 then
				expiryText = string.format("%dH %dM LEFT", math.floor(remaining / 3600), math.floor((remaining % 3600) / 60))
			else
				expiryText = string.format("%dM LEFT", math.max(1, math.floor(remaining / 60)))
			end
		end
		configStore.HomeValueLabels.License.Text = tier .. " // ...." .. hint .. "\n" .. expiryText
		configStore.HomeValueLabels.License.TextSize = 11
		configStore.HomeValueLabels.License.TextColor3 = expiryText == "EXPIRED" and colors.DangerHover or colors.Success
	else
		configStore.HomeValueLabels.License.Text = "FREE // PUBLIC BUILD"
		configStore.HomeValueLabels.License.TextSize = 11
		configStore.HomeValueLabels.License.TextColor3 = colors.Success
	end

	local currentPlayers = #Players:GetPlayers()
	local ok, maxPlayers = pcall(function()
		return Players.MaxPlayers
	end)
	configStore.HomeValueLabels.Players.Text = ok and string.format("%d / %d", currentPlayers, maxPlayers)
		or tostring(currentPlayers)
	otherworldLocationLabel.Text = "Current location: " .. currentPlanet
end

function configStore.RequestYemmaRevive()
	currentPlanet = getCurrentPlanet()
	if not isOtherworldLocation(currentPlanet) then
		reviveStatusLabel.Text = "Available only in Otherworld or HFIL."
		reviveStatusLabel.TextColor3 = colors.DangerHover
		return false
	end

	local now = os.clock()
	if now - lastOtherworldRequestAt < 2 then
		reviveStatusLabel.Text = "Please wait before requesting again."
		reviveStatusLabel.TextColor3 = colors.Muted
		return false
	end
	lastOtherworldRequestAt = now
	serverRemote:FireServer(nil, {
		Module = "OtherworldHandler",
		Action = "Revive",
	})
	reviveStatusLabel.Text = "Revive request sent to King Yemma."
	reviveStatusLabel.TextColor3 = colors.Success
	return true
end

function configStore.SelectTab(name)
	if unloaded or not pages[name] then
		return
	end
	if name == "Otherworld" and not isOtherworldLocation(currentPlanet) then
		return
	end

	currentTab = name
	local meta = configStore.PageMeta and configStore.PageMeta[name]
	if meta then
		configStore.PageTitle.Text = meta.Title
		configStore.PageSubtitle.Text = meta.Subtitle
	end
	for tabName, page in pairs(pages) do
		local selected = tabName == name
		page.Visible = selected
		local button = tabButtons[tabName]
		if button then
			button.BackgroundColor3 = selected and colors.SurfaceRaised or colors.Surface
			button.TextColor3 = selected and colors.Accent or colors.Muted
			local indicator = button:FindFirstChild("Indicator")
			if indicator then indicator.Visible = selected end
		end
	end

	if name == "Doctor" then
		configStore.RequestReport()
	elseif name == "NPCs" then
		refreshNpcTypes()
	elseif name == "TP" then
		tpState.Refresh()
	elseif name == "Character" then
		if next(qolState.ProfileEditor.RaceOrder) == nil then
			task.spawn(qolState.ProfileEditor.LoadMetadata)
		end
	elseif name == "Config" and type(configStore.RefreshDropdown) == "function" then
		configStore.RefreshDropdown()
	end
end

