controller.SetSelectedTrainingStat = function(statName)
	if not configStore.FeatureAccess.AutoTraining then return false end
	if type(statName) ~= "string" then
		return false
	end
	local wanted = string.lower((statName:gsub("%s+", "")))
	for _, definition in ipairs(trainingDefinitions) do
		if wanted == string.lower(definition.Key)
			or wanted == string.lower((definition.Label:gsub("%s+", "")))
			or wanted == string.lower(definition.Button) then
			selectTrainingDefinition(definition)
			return true
		end
	end
	return false
end
